DG.put("krisnaavtaar/24",{"n":24,"title":"ਅਥ ਗੋਵਰਧਨ ਗਿਰਿ ਕਰ ਪਰ ਧਾਰਬੋ","title_roman":"Ath govardhan giri kar par dhaarbo","page":386,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":386,"meaning_status":"draft"},{"type":"verse","number":[335],"number_text":"੩੩੫।","page":386,"lines":[{"gurmukhi":"ਇਸੀ ਭਾਤਿ ਸੋ ਕ੍ਰਿਸਨ ਜੀ ਕੀਨੇ ਦਿਵਸ ਬਿਤੀਤ।","roman":"Isee bhaati so krisan jee keene divas biteet |","meaning_en":"In this way Krishna passed his days.","page":386,"meaning_status":"draft"},{"gurmukhi":"ਹਰਿ ਪੂਜਾ ਕੋ ਦਿਨੁ ਅਯੋ ਗੋਪ ਬਿਚਾਰੀ ਚੀਤਿ। ੩੩੫।","roman":"Hari poojaa ko dinu ayo gop bichaaree cheeti | 335 |","meaning_en":"The day of worship of Hari came, and the cowherds thought about it in their minds.","page":386,"meaning_status":"draft","note":"ਹਰਿ ਪੂਜਾ: here the worship of Indra (Hari can also mean Indra), as the next verse shows."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":386,"meaning_status":"draft"},{"type":"verse","number":[336],"number_text":"੩੩੬।","page":386,"lines":[{"gurmukhi":"ਆਯੋ ਹੈ ਇੰਦ੍ਰ ਕੀ ਪੂਜਾ ਕੋ ਦ੍ਯੋਸ ਸਭੋ ਮਿਲਿ ਗੋਪਿਨ ਬਾਤ ਉਚਾਰੀ।","roman":"Aayo hai indr kee poojaa ko dyos sabho mili gopin baat uchaaree |","meaning_en":"'The day of Indra's worship has come,' all the cowherds said together;","page":386,"meaning_status":"draft"},{"gurmukhi":"ਭੋਜਨ ਭਾਤਿ ਅਨੇਕਨ ਕੋ ਰੁ ਪੰਚਾਮ੍ਰਿਤ ਕੀ ਕਰੋ ਜਾਇ ਤਯਾਰੀ।","roman":"Bhojan bhaati anekan ko ru panchaamrit kee karo jaai tayaaree |","meaning_en":"'go and prepare food of many kinds, and panchamrit.'","page":386,"meaning_status":"draft"},{"gurmukhi":"ਨੰਦ ਕਹਿਯੋ ਜਬ ਗੋਪਿਨ ਸੋ ਬਿਧਿ ਅਉਰ ਚਿਤੀ ਮਨ ਬੀਚ ਮੁਰਾਰੀ।","roman":"Nand kahiyo jab gopin so bidhi aur chitee man beech muraaree |","meaning_en":"When Nand said this to the cowherds, Murari thought of another way in his mind:","page":387,"meaning_status":"draft","note":"Murari: Krishna."},{"gurmukhi":"ਕੋ ਬਪੁਰਾ ਮਘਵਾ ਹਮਰੀ ਸਮ ਪੂਜਨ ਜਾਤ ਜਹਾ ਬ੍ਰਿਜ ਨਾਰੀ। ੩੩੬।","roman":"Ko bapuraa maghvaa hamree sam poojan jaat jahaa brij naaree | 336 |","meaning_en":"'What is wretched Indra, equal to me, that the women of Braj go to worship him?'","page":387,"meaning_status":"draft","note":"ਮਘਵਾ: Indra. ਹਮਰੀ ਸਮ: read as 'compared to me'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":387,"meaning_status":"draft"},{"type":"verse","number":[337],"number_text":"੩੩੭।","page":387,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਬੋਲਿਯੋ ਕਾਨ੍ਹ ਕਰੁਣਾ ਨਿਧਾਨ ਤਾਤ","roman":"Ih bidhi boliyo kaanh karunaa nidhaan taat","meaning_en":"Kanh, the treasure of mercy, spoke thus: 'Father,","page":387,"meaning_status":"draft"},{"gurmukhi":"ਕਾਹੇ ਕੇ ਨਵਿਤ ਕੋ ਸਾਮ੍ਰਿਗੀ ਤੈ ਬਨਾਈ ਹੈ।","roman":"Kaahe ke navit ko saamrigee tai banaaee hai |","meaning_en":"for whose sake have you made these offerings ready?'","page":387,"meaning_status":"draft","note":"ਨਵਿਤ: read as 'sake, purpose' (nimitt); uncertain."},{"gurmukhi":"ਕਹਿਯੋ ਐਸੇ ਨੰਦ ਜੋ ਤ੍ਰਿਲੋਕੀਪਤਿ ਭਾਖੀਅਤ","roman":"Kahiyo aise nand jo trilokeepti bhaakheeat","meaning_en":"Nand said thus: 'He who is called the lord of the three worlds,","page":387,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਕੋ ਬਨਾਈ ਹਰਿ ਕਹਿ ਕੈ ਸੁਨਾਈ ਹੈ।","roman":"Taahee ko banaaee hari kahi kai sunaaee hai |","meaning_en":"for him these are made.' So he told Hari.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਕਾਹੇ ਕੇ ਨਵਿਤ ਕਹਿਯੋ ਬਾਰਿਦ ਤ੍ਰਿਨਨ ਕਾਜ","roman":"Kaahe ke navit kahiyo baarid trinan kaaj","meaning_en":"'Why for him?' he asked. 'He sends the clouds for the sake of the grass;","page":387,"meaning_status":"draft"},{"gurmukhi":"ਗਊਅਨ ਕੀ ਰਛ ਕਰੀ ਅਉ ਹੋਤ ਆਈ ਹੈ।","roman":"Gaooan kee rachh karee au hot aaee hai |","meaning_en":"he has protected the cows, and so it has always been done.'","page":387,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿਯੋ ਭਗਵਾਨ ਏਤੋ ਲੋਗ ਹੈ ਅਜਾਨ ਬ੍ਰਿਜ","roman":"Kahiyo bhagvaan eto log hai ajaan brij","meaning_en":"The Lord said, 'The people of Braj are so ignorant:","page":387,"meaning_status":"draft"},{"gurmukhi":"ਈਸ ਤੇ ਹੋਤ ਨਹੀ ਮਘਵਾ ਤੇ ਗਾਈ ਹੈ। ੩੩੭।","roman":"Ees te hot nahee maghvaa te gaaee hai | 337 |","meaning_en":"it comes from God, not from Indra; that is what is sung.'","page":387,"meaning_status":"draft","note":"Second half sense uncertain."}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"Kanh said:","page":387,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":387,"meaning_status":"draft"},{"type":"verse","number":[338],"number_text":"੩੩੮।","page":387,"lines":[{"gurmukhi":"ਹੈ ਨਹੀ ਮੇਘੁ ਸੁਰਪਤਿ ਹਾਥਿ ਸੁ ਤਾਤ ਸੁਨੋ ਅਰੁ ਲੋਕ ਸਭੈ ਰੇ।","roman":"Hai nahee meghu surapti haathi su taat suno aru lok sabhai re |","meaning_en":"'The clouds are not in the hand of the lord of the gods; listen, father, and all you people.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਭੰਜਨ ਭਉ ਅਨਭੈ ਭਗਵਾਨ ਸੁ ਦੇਤ ਸਭੈ ਜਨ ਕੋ ਅਰੁ ਲੈ ਰੇ।","roman":"Bhanjan bhau anbhai bhagvaan su det sabhai jan ko aru lai re |","meaning_en":"The fearless Lord, the destroyer of fear, gives to all people, and takes back.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਕਿਉ ਮਘਵਾ ਤੁਮ ਪੂਜਨ ਜਾਤ ਕਰੋ ਤੁਮ ਸੇਵ ਹਿਤੰ ਚਿਤ ਕੈ ਰੇ।","roman":"Kiu maghvaa tum poojan jaat karo tum sev hitan chit kai re |","meaning_en":"Why do you go to worship Indra? Serve the Lord with love in your hearts.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਯਾਨ ਧਰੋ ਸਭ ਹੀ ਮਿਲ ਕੈ ਸਭ ਬਾਤਨ ਕੋ ਤੁਮ ਕੋ ਫਲ ਦੈ ਰੇ। ੩੩੮।","roman":"Dhyaan dharo sabh hee mil kai sabh baatan ko tum ko phal dai re | 338 |","meaning_en":"Meditate on him, all of you together; he will give you the fruit of everything.'","page":387,"meaning_status":"draft"}]},{"type":"verse","number":[339],"number_text":"੩੩੯।","page":387,"lines":[{"gurmukhi":"ਬਾਸਵ ਜਗ੍ਯਨ ਕੈ ਬਸਿ ਮੇਘ ਕਿਧੋ ਬ੍ਰਹਮਾ ਇਹ ਬਾਤ ਉਚਾਰੈ।","roman":"Baasav jagyan kai basi megh kidho brahmaa ih baat uchaarai |","meaning_en":"'Is Indra, because of sacrifices, master of the clouds, or does Brahma say this?","page":387,"meaning_status":"draft","note":"ਬਾਸਵ: Indra. Line sense uncertain."},{"gurmukhi":"ਲੋਗਨ ਕੇ ਪ੍ਰਤਿਪਾਰਨ ਕੋ ਹਰਿ ਸੂਰਜ ਮੈ ਹੁਇ ਕੈ ਜਲ ਡਾਰੈ।","roman":"Logan ke pratipaaran ko hari sooraj mai hui kai jal daarai |","meaning_en":"To sustain the people, Hari, dwelling in the sun, pours down the water.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਕਉਤੁਕ ਦੇਖਤ ਜੀਵਨ ਕੋ ਪਿਖਿ ਕਉਤੁਕ ਹ੍ਵੈ ਸਿਵ ਤਾਹਿ ਸੰਘਾਰੈ।","roman":"Kautuk dekhat jeevan ko pikhi kautuk hvai siv taahi sanghaarai |","meaning_en":"Watching the play of living beings, he becomes Shiva in his play and destroys them.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਵਹ ਏਕ ਕਿਧੋ ਸਰਤਾ ਸਮ ਬਾਹਨ ਕੇ ਜਮ ਬਾਹੇ ਬਿਥਾਰੈ। ੩੩੯।","roman":"Hai vah ek kidho sartaa sam baahan ke jam baahe bithaarai | 339 |","meaning_en":"He is one, like a river that spreads out into many streams.'","page":387,"meaning_status":"draft","note":"ਬਾਹਨ ਕੇ ਜਮ ਬਾਹੇ ਬਿਥਾਰੈ: sense uncertain."}]},{"type":"verse","number":[340],"number_text":"੩੪੦।","page":387,"lines":[{"gurmukhi":"ਪਾਥਰ ਪੈ ਜਲ ਪੈ ਨਗ ਪੈ ਤਰ ਪੈ ਧਰ ਪੈ ਅਰੁ ਅਉਰ ਨਰੀ ਹੈ।","roman":"Paathar pai jal pai nag pai tar pai dhar pai aru aur naree hai |","meaning_en":"'On stone, on water, on mountain, on tree, on earth, and on other men,","page":387,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵਨ ਪੈ ਅਰੁ ਦੈਤਨ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਉ ਮੁਰਾਰਿ ਹਰੀ ਹੈ।","roman":"Devan pai aru daitan pai kabi syaam kahai au muraari haree hai |","meaning_en":"on gods and on demons, says the poet Shyam, is Murari, Hari.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਪਛਨ ਪੈ ਮ੍ਰਿਗਰਾਜਨ ਪੈ ਮ੍ਰਿਗ ਕੇ ਗਨ ਪੈ ਫੁਨਿ ਹੋਤ ਖਰੀ ਹੈ।","roman":"Pachhan pai mrigraajan pai mrig ke gan pai phuni hot kharee hai |","meaning_en":"On birds, on lions, on herds of deer, he stands present.","page":387,"meaning_status":"draft","note":"ਹੋਤ ਖਰੀ: read as 'is present, stands'; uncertain."},{"gurmukhi":"ਭੇਦ ਕਹਿਯੋ ਇਹ ਬਾਤ ਸਭੈ ਇਨਹੂੰ ਇਹ ਕੀ ਕਹਾ ਪੂਜ ਕਰੀ ਹੈ। ੩੪੦।","roman":"Bhed kahiyo ih baat sabhai inhoon ih kee kahaa pooj karee hai | 340 |","meaning_en":"This is the secret I have told; yet what worship of him have these people done?'","page":387,"meaning_status":"draft"}]},{"type":"verse","number":[341],"number_text":"੩੪੧।","page":387,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਹਸਿ ਕੈ ਹਰਿ ਬਾਤ ਕਹੀ ਨੰਦ ਪੈ ਹਮਰੀ ਬਿਨਤੀ ਸੁਨਿ ਲਈਯੈ।","roman":"Tab hee hasi kai hari baat kahee nand pai hamree bintee suni laeeyai |","meaning_en":"Then Hari, smiling, said to Nand, 'Listen to my request.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਹੁ ਬਿਪਨ ਕੋ ਮੁਖ ਗਊਅਨ ਪੂਜਨ ਜਾ ਗਿਰਿ ਹੈ ਤਹ ਜਈਯੈ।","roman":"Poojhu bipan ko mukh gaooan poojan jaa giri hai tah jaeeyai |","meaning_en":"Worship the Brahmins first, and the cows; go to where the mountain is to worship.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਗਊਅਨ ਕੋ ਪਯ ਪੀਜਤ ਹੈ ਗਿਰਿ ਕੇ ਚੜ੍ਹਿਐ ਮਨਿ ਆਨੰਦ ਪਈਯੈ।","roman":"Gaooan ko pay peejat hai giri ke charhiai mani aanand paeeyai |","meaning_en":"We drink the milk of the cows, and by climbing the mountain we find joy in our hearts.","page":387,"meaning_status":"draft"},{"gurmukhi":"ਦਾਨ ਦਏ ਤਿਨ ਕੇ ਜਸੁ ਹ੍ਯਾ ਪਰਲੋਕ ਗਏ ਜੁ ਦਯੋ ਸੋਊ ਖਈਯੈ। ੩੪੧।","roman":"Daan dae tin ke jasu hyaa parlok gae ju dayo so'oo khaeeyai | 341 |","meaning_en":"Giving gifts to them brings fame here; and what is given is enjoyed when one goes to the next world.'","page":387,"meaning_status":"draft"}]},{"type":"verse","number":[342],"number_text":"੩੪੨।","page":388,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਭਗਵਾਨ ਕਹੀ ਪਿਤ ਸੋ ਇਕ ਬਾਤ ਸੁਨੋ ਤੁ ਕਹੋ ਮਮ ਤੋ ਸੋ।","roman":"Tab hee bhagvaan kahee pit so ik baat suno tu kaho mam to so |","meaning_en":"Then the Lord said to his father, 'Listen to one thing I tell you.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਹੁ ਜਾਇ ਸਬੈ ਗਿਰਿ ਕੌ ਤੁਮ ਇੰਦ੍ਰ ਕਰੈ ਕੁਪਿ ਕਿਆ ਫੁਨਿ ਤੋ ਸੋ।","roman":"Poojhu jaai sabai giri kau tum indr karai kupi kiaa phuni to so |","meaning_en":"All of you go and worship the mountain; what can Indra do to you in his anger?","page":388,"meaning_status":"draft"},{"gurmukhi":"ਮੋ ਸੋ ਸੁਪੂਤ ਭਯੋ ਤੁਮਰੇ ਗ੍ਰਿਹਿ ਮਾਰਿ ਡਰੋ ਮਘਵਾ ਸੰਗਿ ਝੋਸੋ।","roman":"Mo so supoot bhayo tumre grihi maari daro maghvaa sangi jhoso |","meaning_en":"A good son like me has been born in your house; I will kill Indra and throw him into the fire.","page":388,"meaning_status":"draft","note":"ਝੋਸੋ: read as 'throw in (the fire)'; uncertain."},{"gurmukhi":"ਰਹਸਿ ਕਹੀ ਪਿਤ ਪਾਰਥ ਕੀ ਤਜਿ ਹੈ ਇਹ ਜਾ ਹਮਰੀ ਅਨ ਮੋ ਸੋ। ੩੪੨।","roman":"Rahsi kahee pit paarath kee taji hai ih jaa hamree an mo so | 342 |","meaning_en":"I tell you in secret: Arjun's father will leave this place, unable to stand against me.'","page":388,"meaning_status":"draft","note":"ਰਹਸਿ ਕਹੀ ਪਿਤ ਪਾਰਥ ਕੀ ਤਜਿ ਹੈ ਇਹ ਜਾ ਹਮਰੀ ਅਨ ਮੋ ਸੋ: sense unclear; Arjun's father = Indra. Very uncertain."}]},{"type":"verse","number":[343],"number_text":"੩੪੩।","page":388,"lines":[{"gurmukhi":"ਤਾਤ ਕੀ ਬਾਤ ਜੁ ਨੰਦ ਸੁਨੀ ਸਭ ਬਾਤ ਭਲੀ ਸਿਰ ਊਪਰ ਬਾਧੀ।","roman":"Taat kee baat ju nand sunee sabh baat bhalee sir oopar baadhee |","meaning_en":"When Nand heard his son's words, he took the whole good counsel upon his head.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਬਾਕੋ ਕੀ ਕੈ ਮੁਰਵੀ ਤਨ ਕੈ ਧਨੁ ਤੀਛਨ ਮਤ ਮਹਾ ਸਰ ਸਾਧੀ।","roman":"Baako kee kai murvee tan kai dhanu teechhan mat mahaa sar saadhee |","meaning_en":"It was as if, bending the curved bow and drawing the string, he aimed the sharp arrow of thought.","page":388,"meaning_status":"draft","note":"Sense uncertain."},{"gurmukhi":"ਸ੍ਰਉਨਨ ਮੈ ਸੁਨਤਿਯੋ ਇਹ ਬਾਤ ਕਬੁਧਿ ਗੀ ਛੂਟਿ ਚਿਰੀ ਜਿਹ ਫਾਧੀ।","roman":"Sraunan mai suntiyo ih baat kabudhi gee chhooti chiree jih phaadhee |","meaning_en":"As soon as he heard this in his ears, his wrong thinking was let go, like a trapped bird set free.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿ ਕੀ ਬਾਰਿਦ ਹ੍ਵੈ ਕਰਿ ਗਿਆਨ ਨਿਵਾਰ ਦਈ ਉਮਡੀ ਜਨੁ ਆਧੀ।੩੪੩।","roman":"Mohi kee baarid hvai kari giaan nivaar daee umdee janu aadhee | 343 |","meaning_en":"Wisdom, like a cloud, dispelled the gathering storm of attachment.","page":388,"meaning_status":"draft","note":"Image reversed in sense: read as wisdom dispelling delusion; uncertain."}]},{"type":"verse","number":[344],"number_text":"੩੪੪।","page":388,"lines":[{"gurmukhi":"ਨੰਦ ਬੁਲਾਇ ਕੈ ਗੋਪ ਲਏ ਹਰਿ ਆਇਸੁ ਮਾਨਿ ਸਿਰ ਊਪਰ ਲੀਆ।","roman":"Nand bulaai kai gop lae hari aaisu maani sir oopar leeaa |","meaning_en":"Nand called the cowherds, and took Hari's order upon his head.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਹੁ ਗਊਅਨ ਅਉ ਮੁਖ ਬਿਪਨ ਭਈਅਨ ਸੋ ਇਹ ਆਇਸੁ ਕੀਆ।","roman":"Poojhu gaooan au mukh bipan bhaeean so ih aaisu keeaa |","meaning_en":"'Worship the cows, and first the Brahmins,' this command he gave to the brothers.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਕਹਿਯੋ ਹਮ ਤਉ ਕਹਿਯੋ ਤੋ ਸੋ ਗ੍ਯਾਨ ਭਲੋ ਮਨ ਮੈ ਸਮਝੀਆ।","roman":"Pheri kahiyo ham tau kahiyo to so gyaan bhalo man mai samjheeaa |","meaning_en":"Then he said, 'I tell you this; I have understood good wisdom in my mind.'","page":388,"meaning_status":"draft"},{"gurmukhi":"ਚਿਤ ਦਯੋ ਸਭਨੋ ਹਮ ਸੋ ਤਿਹੁ ਲੋਗਨ ਕੋ ਪਤਿ ਚਿਤਨ ਕੀਆ। ੩੪੪।","roman":"Chit dayo sabhno ham so tihu logan ko pati chitan keeaa | 344 |","meaning_en":"All gave their hearts to him, and thought on the lord of the three worlds.","page":388,"meaning_status":"draft"}]},{"type":"verse","number":[345],"number_text":"੩੪੫।","page":388,"lines":[{"gurmukhi":"ਗੋਪ ਚਲੇ ਉਠ ਕੈ ਗ੍ਰਿਹ ਕੋ ਬ੍ਰਿਜ ਕੇ ਪਤਿ ਕੋ ਫੁਨਿ ਆਇਸੁ ਪਾਈ।","roman":"Gop chale uth kai grih ko brij ke pati ko phuni aaisu paaee |","meaning_en":"Having received the order of the lord of Braj, the cowherds rose and went home.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਅਛਤ ਧੂਪ ਪੰਚਾਮ੍ਰਿਤ ਦੀਪਕ ਪੂਜਨ ਕੀ ਸਭ ਭਾਤਿ ਬਨਾਈ।","roman":"Achhat dhoop panchaamrit deepak poojan kee sabh bhaati banaaee |","meaning_en":"Rice, incense, panchamrit and lamps: they prepared everything for the worship.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕੁਰਬੇ ਅਪਨੈ ਸਭ ਸੰਗਿ ਚਲੇ ਗਿਰਿ ਕੌ ਸਭ ਢੋਲ ਬਜਾਈ।","roman":"Lai kurbe apnai sabh sangi chale giri kau sabh dhol bajaaee |","meaning_en":"Taking their families with them, they all went to the mountain beating drums.","page":388,"meaning_status":"draft","note":"ਕੁਰਬੇ: read as 'families, households'."},{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਜਸੁਧਾ ਊ ਚਲੀ ਭਗਵਾਨ ਚਲੇ ਮੁਸਲੀ ਸੰਗਿ ਭਾਈ। ੩੪੫।","roman":"Nand chaliyo jasudhaa oo chalee bhagvaan chale muslee sangi bhaaee | 345 |","meaning_en":"Nand went, and Yashoda went too, and the Lord went with his brother Balram.","page":388,"meaning_status":"draft"}]},{"type":"verse","number":[346],"number_text":"੩੪੬।","page":388,"lines":[{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਕੁਰਬੇ ਸੰਗਿ ਲੈ ਕਰਿ ਤੀਰ ਜਬੈ ਗਿਰਿ ਕੇ ਚਲਿ ਆਯੋ।","roman":"Nand chaliyo kurbe sangi lai kari teer jabai giri ke chali aayo |","meaning_en":"Nand went along with the families, and came to the foot of the mountain.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਗਊਅਨ ਘਾਸ ਚਰਾਇਤ ਸੋ ਬਹੁ ਬਿਪਨ ਖੀਰ ਆਹਾਰ ਖਵਾਯੋ।","roman":"Gaooan ghaas charaait so bahu bipan kheer aahaar khavaayo |","meaning_en":"He had the cows grazed on grass and fed many Brahmins with kheer.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਪਰੋਸਨ ਲਾਗ ਜਦੁਪਤਿ ਗੋਪ ਸਭੈ ਮਨ ਮੈ ਸੁਖ ਪਾਯੋ।","roman":"Aap parosan laag jadupti gop sabhai man mai sukh paayo |","meaning_en":"The lord of the Yadavs himself began to serve the food, and all the cowherds were happy at heart.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰ ਚੜਾਇ ਲਏ ਰਥ ਪੈ ਚਲ ਕੈ ਇਹ ਕਉਤਕ ਅਉਰ ਬਨਾਯੋ। ੩੪੬।","roman":"Baar charaai lae rath pai chal kai ih kautak aur banaayo | 346 |","meaning_en":"Putting the children up in carts, he went on and staged another wonder.","page":388,"meaning_status":"draft","note":"ਬਾਰ: read as 'children'; uncertain."}]},{"type":"verse","number":[347],"number_text":"੩੪੭।","page":388,"lines":[{"gurmukhi":"ਕਉਤਕ ਏਕ ਬਿਚਾਰ ਜਦੁਪਤਿ ਸੂਰਤਿ ਏਕ ਧਰੀ ਗਿਰ ਬਾਕੀ।","roman":"Kautak ek bichaar jadupti soorti ek dharee gir baakee |","meaning_en":"The lord of the Yadavs thought of a wonder: he took on a form, another mountain,","page":388,"meaning_status":"draft","note":"ਗਿਰ ਬਾਕੀ: read as 'of the mountain'; uncertain."},{"gurmukhi":"ਸ੍ਰਿੰਗ ਬਨਾਇ ਧਰੀ ਨਗ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਹ ਗਮ੍ਯ ਨ ਕਾ ਕੀ।","roman":"Sring banaai dharee nag kai kabi syaam kahai jah gamy na kaa kee |","meaning_en":"and set it up as a peak of the mountain, says the poet Shyam, where none could reach.","page":388,"meaning_status":"draft"},{"gurmukhi":"ਭੋਜਨ ਪਾਤ ਪ੍ਰਤਛਿ ਕਿਧੋ ਵਹ ਬਾਤ ਲਖੀ ਨ ਪਰੈ ਕਛੁ ਵਾ ਕੀ।","roman":"Bhojan paat pratchhi kidho vah baat lakhee na parai kachhu vaa kee |","meaning_en":"It ate the food openly, yet nothing about it could be made out.","page":388,"meaning_status":"draft","note":"ਭੋਜਨ ਪਾਤ ਪ੍ਰਤਛਿ: read as 'it ate the food before their eyes'; uncertain."},{"gurmukhi":"ਕਉਤਕ ਏਕ ਲਖੈ ਭਗਵਾਨ ਅਉ ਜੋ ਪਿਖਵੈ ਅਟਕੈ ਮਤਿ ਤਾ ਕੀ। ੩੪੭।","roman":"Kautak ek lakhai bhagvaan au jo pikhvai atkai mati taa kee | 347 |","meaning_en":"The Lord alone knows this wonder, and whoever sees it, his understanding is held fast.","page":388,"meaning_status":"draft"}]},{"type":"verse","number":[348],"number_text":"੩੪੮।","page":389,"lines":[{"gurmukhi":"ਤੌ ਭਗਵਾਨ ਤਬੈ ਹਸਿ ਕੈ ਸਮ ਅੰਮ੍ਰਿਤ ਬਾਤ ਤਿਨੈ ਸੰਗਿ ਭਾਖੀ।","roman":"Tau bhagvaan tabai hasi kai sam anmrit baat tinai sangi bhaakhee |","meaning_en":"Then the Lord, smiling, spoke words like nectar to them:","page":389,"meaning_status":"draft"},{"gurmukhi":"ਭੋਜਨ ਖਾਤ ਦਯੋ ਹਮਰੋ ਗਿਰਿ ਲੋਕ ਸਭੈ ਪਿਖਵੋ ਤੁਮ ਆਖੀ।","roman":"Bhojan khaat dayo hamro giri lok sabhai pikhvo tum aakhee |","meaning_en":"'The mountain is eating the food we gave; all you people, see it with your own eyes.'","page":389,"meaning_status":"draft"},{"gurmukhi":"ਹੋਇ ਰਹੇ ਬਿਸਮੈ ਸਭ ਗੋਪ ਸੁਨੀ ਹਰਿ ਕੇ ਮੁਖ ਤੇ ਜਬ ਸਾਖੀ।","roman":"Hoi rahe bismai sabh gop sunee hari ke mukh te jab saakhee |","meaning_en":"All the cowherds were astonished when they heard this testimony from Hari's mouth.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਗਿਆਨ ਜਨਾਵਰ ਕੀ ਲਈ ਬਾਜ ਹ੍ਵੈ ਗਵਾਰਨ ਕਾਨ੍ਹ ਦਈ ਜਬ ਚਾਖੀ।੩੪੮।","roman":"Giaan janaavar kee laee baaj hvai gavaaran kaanh daee jab chaakhee | 348 |","meaning_en":"When Kanh gave the cowherds this taste, the hawk of wisdom seized the bird of their ignorance.","page":389,"meaning_status":"draft","note":"ਗਿਆਨ ਜਨਾਵਰ ਕੀ ਲਈ ਬਾਜ ਹ੍ਵੈ: sense uncertain."}]},{"type":"verse","number":[349],"number_text":"੩੪੯।","page":389,"lines":[{"gurmukhi":"ਅੰਜੁਲ ਜੋਰਿ ਸਭੈ ਬ੍ਰਿਜ ਕੇ ਜਨ ਕੋਟਿ ਪ੍ਰਨਾਮ ਕਰੈ ਹਰਿ ਆਗੇ।","roman":"Anjul jori sabhai brij ke jan koti pranaam karai hari aage |","meaning_en":"With palms joined, all the people of Braj make countless bows before Hari.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਭੂਲ ਗਈ ਸਭ ਕੋ ਮਘਵਾ ਸੁਧਿ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਭੀਤਰ ਪਾਗੇ।","roman":"Bhool gaee sabh ko maghvaa sudhi kaanh hee ke ras bheetar paage |","meaning_en":"All forgot about Indra and were steeped in the love of Kanh alone.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਸੋਵਤ ਥੇ ਜੁ ਪਰੇ ਬਿਖ ਮੈ ਸਭ ਧ੍ਯਾਨ ਲਗੇ ਹਰਿ ਕੇ ਜਨ ਜਾਗੇ।","roman":"Sovat the ju pare bikh mai sabh dhyaan lage hari ke jan jaage |","meaning_en":"Those who had lain asleep in poison awoke, fixing their attention on Hari.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਗਈ ਸੁਧ ਭੂਲ ਸਭੋ ਇਕ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਮੈ ਅਨੁਰਾਗੇ। ੩੪੯।","roman":"Aur gaee sudh bhool sabho ik kaanh hee ke ras mai anuraage | 349 |","meaning_en":"All forgot every other thought, devoted to the love of Kanh alone.","page":389,"meaning_status":"draft"}]},{"type":"verse","number":[350],"number_text":"੩੫੦।","page":389,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਸਭ ਕੋ ਹਸਿ ਕੇ ਮਿਲਿ ਧਾਮਿ ਚਲੋ ਜੋਊ ਹੈ ਹਰਤਾ ਅਘ।","roman":"Kaanh kahee sabh ko hasi ke mili dhaami chalo jo'oo hai hartaa agh |","meaning_en":"Kanh, the remover of sin, said to them all, smiling, 'Let us all go home together.'","page":389,"meaning_status":"draft"},{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਬਲਭਦ੍ਰ ਚਲਿਯੋ ਜਸੁਧਾ ਊ ਚਲੀ ਨੰਦ ਲਾਲ ਬਿਨਾਨਘ।","roman":"Nand chaliyo balbhadr chaliyo jasudhaa oo chalee nand laal binaanagh |","meaning_en":"Nand went, Balbhadra went, Yashoda went too, and Nand's sinless darling.","page":389,"meaning_status":"draft","note":"ਬਿਨਾਨਘ: read as 'sinless' (anagh); uncertain."},{"gurmukhi":"ਪੂਜ ਜਬੈ ਇਨਹੂੰ ਨ ਕਰੀ ਤਬ ਹੀ ਕੁਪਿਓ ਇਨ ਪੈ ਧਰਤਾ ਪ੍ਰਘ।","roman":"Pooj jabai inhoon na karee tab hee kupio in pai dhartaa pragh |","meaning_en":"When they did not perform his worship, the wielder of the club grew angry with them.","page":389,"meaning_status":"draft","note":"ਧਰਤਾ ਪ੍ਰਘ: read as Indra, holder of the iron club (parigh); uncertain."},{"gurmukhi":"ਬੇਦਨ ਮਧ ਕਹੀ ਇਨਿ ਭੀਮ ਤੇ ਮਾਰਿ ਡਰਿਯੋ ਛਲ ਸੋ ਪਤਵਾ ਮਘ। ੩੫੦।","roman":"Bedan madh kahee ini bheem te maari dariyo chhal so patvaa magh | 350 |","meaning_en":"The Vedas say this Indra killed Bhim by a trick and threw him down.","page":389,"meaning_status":"draft","note":"ਭੀਮ ... ਪਤਵਾ ਮਘ: sense unclear; Bhim may be a demon's name. Uncertain."}]},{"type":"verse","number":[351],"number_text":"੩੫੧।","page":389,"lines":[{"gurmukhi":"ਭੂ ਸੁਤ ਸੋ ਲਰ ਕੈ ਜਿਨ ਹੂੰ ਨਵਸਾਤ ਛੁਡਾਇ ਲਈ ਬਰਮੰਙਾ।","roman":"Bhoo sut so lar kai jin hoon navsaat chhudaai laee barmanngaa |","meaning_en":"He who fought the son of the Earth and set free sixteen thousand women,","page":389,"meaning_status":"draft","note":"Read as Krishna, who defeated Narakasur (son of Earth) and freed the captive women. ਨਵਸਾਤ, ਬਰਮੰਙਾ: uncertain."},{"gurmukhi":"ਆਦਿ ਸਤਜੁਗ ਕੇ ਮੁਰ ਕੇ ਗੜ ਤੋਰਿ ਦਏ ਸਭ ਜਿਉ ਕਚ ਬੰਙਾ।","roman":"Aadi satjug ke mur ke gar tori dae sabh jiu kach banngaa |","meaning_en":"who in the first age, the Satyug, broke all the forts of Mur like glass bangles,","page":389,"meaning_status":"draft","note":"Mur: a demon."},{"gurmukhi":"ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਅਰੁ ਦੇਵਨ ਹਾਰ ਇਹੀ ਜੁਗ ਸੰਙਾ।","roman":"Hai kartaa sabh hee jag ko aru devan haar ihee jug sanngaa |","meaning_en":"who is the maker of the whole world and the destroyer of the ages:","page":389,"meaning_status":"draft","note":"ਸੰਙਾ: read as 'destruction'; uncertain."},{"gurmukhi":"ਲੋਕਨ ਕੋ ਪਤਿ ਸੋ ਮਤਿ ਮੰਦ ਬਿਬਾਦ ਕਰੈ ਮਘਵਾ ਮਤਿ ਲੰਙਾ। ੩੫੧।","roman":"Lokan ko pati so mati mand bibaad karai maghvaa mati lanngaa | 351 |","meaning_en":"with him, the lord of the worlds, the dull-witted Indra, lame of mind, quarrels.","page":389,"meaning_status":"draft"}]},{"type":"verse","number":[352],"number_text":"੩੫੨।","page":389,"lines":[{"gurmukhi":"ਗੋਪਨ ਸੋ ਖਿਝ ਕੈ ਮਘਵਾ ਤਜਿ ਕੈ ਮਨਿ ਆਨੰਦ ਕੋਪ ਰਚੇ।","roman":"Gopan so khijh kai maghvaa taji kai mani aanand kop rache |","meaning_en":"Vexed with the cowherds, Indra gave up joy in his heart and grew angry.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗਿ ਮੇਘਨ ਜਾਇ ਕਹੀ ਬਰਖੋ ਬ੍ਰਿਜ ਪੈ ਰਸ ਬੀਰ ਹੀ ਮਧ ਗਚੇ।","roman":"Sangi meghan jaai kahee barkho brij pai ras beer hee madh gache |","meaning_en":"He went and said to the clouds, steeped in heroic fury, 'Rain upon Braj.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਕਰੀਯੋ ਬਰਖਾ ਇਤਨੀ ਉਨ ਪੈ ਜਿਹ ਤੇ ਫੁਨਿ ਗੋਪ ਨ ਏਕ ਬਚੇ।","roman":"Kareeyo barkhaa itnee un pai jih te phuni gop na ek bache |","meaning_en":"Pour so much rain on them that not one cowherd is left alive.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਭੈਨਨ ਭ੍ਰਾਤਨ ਤਾਤਨ ਪਊਤ੍ਰਨ ਤਊਅਨ ਮਾਰਹੁ ਸਾਥ ਚਚੇ। ੩੫੨।","roman":"Sabh bhainan bhraatan taatan paootran taooan maarhu saath chache | 352 |","meaning_en":"Kill them all: sisters, brothers, fathers, grandsons, father's elder brothers, and younger uncles too.'","page":389,"meaning_status":"draft"}]},{"type":"verse","number":[353],"number_text":"੩੫੩।","page":389,"lines":[{"gurmukhi":"ਆਇਸੁ ਮਾਨਿ ਪੁਰੰਦਰ ਕੋ ਅਪਨੇ ਸਭ ਮੇਘਨ ਕਾਛ ਸੁ ਕਾਛੇ।","roman":"Aaisu maani purandar ko apne sabh meghan kaachh su kaachhe |","meaning_en":"Obeying Indra's order, all the clouds put on their armour.","page":389,"meaning_status":"draft","note":"ਪੁਰੰਦਰ: Indra."},{"gurmukhi":"ਧਾਇ ਚਲੇ ਬ੍ਰਿਜ ਕੇ ਮਰਬੇ ਕਹੁ ਘੇਰਿ ਦਸੋ ਦਿਸ ਤੇ ਘਨ ਆਛੇ।","roman":"Dhaai chale brij ke marbe kahu gheri daso dis te ghan aachhe |","meaning_en":"They rushed off to kill the people of Braj; the fine clouds surrounded it from all ten directions.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪ ਭਰੇ ਅਰੁ ਬਾਰਿ ਭਰੇ ਬਧਬੇ ਕਉ ਚਲੇ ਚਰੀਆ ਜੋਊ ਬਾਛੇ।","roman":"Kop bhare aru baari bhare badhbe kau chale chareeaa jo'oo baachhe |","meaning_en":"Full of anger and full of water, they went to kill the grazing calves.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਛਿਪ੍ਰ ਚਲੇ ਕਰਬੇ ਨ੍ਰਿਪ ਕਾਰਜ ਛੋਡਿ ਚਲੇ ਬਨਿਤਾ ਸੁਤ ਪਾਛੇ। ੩੫੩।","roman":"Chhipr chale karbe nrip kaaraj chhodi chale banitaa sut paachhe | 353 |","meaning_en":"They went swiftly to do their king's work, leaving their wives and sons behind.","page":389,"meaning_status":"draft"}]},{"type":"verse","number":[354],"number_text":"੩੫੪।","page":389,"lines":[{"gurmukhi":"ਦੈਤ ਸੰਖਾਸੁਰ ਕੇ ਮਰਬੇ ਕਹੁ ਰੂਪੁ ਧਰਿਯੋ ਜਲ ਮੈ ਜਿਨਿ ਮਛਾ।","roman":"Dait sankhaasur ke marbe kahu roopu dhariyo jal mai jini machhaa |","meaning_en":"He who, to kill the demon Sankhasur, took the form of a fish in the water;","page":389,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧੁ ਮਥਿਯੋ ਜਬ ਹੀ ਅਸੁਰਾਸੁਰ ਮੇਰੁ ਤਰੈ ਭਯੋ ਕਛਪ ਹਛਾ।","roman":"Sindhu mathiyo jab hee asuraasur meru tarai bhayo kachhap hachhaa |","meaning_en":"who, when the gods and demons churned the ocean, became the fine tortoise beneath Mount Meru:","page":389,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਅਬ ਕਾਨ੍ਹ ਭਯੋ ਇਹ ਠਉਰਿ ਚਰਾਵਤ ਹੈ ਬ੍ਰਿਜ ਕੇ ਸਭ ਬਛਾ।","roman":"So ab kaanh bhayo ih thauri charaavat hai brij ke sabh bachhaa |","meaning_en":"he has now become Kanh in this place, and grazes all the calves of Braj.","page":389,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲ ਦਿਖਾਵਤ ਹੈ ਜਗ ਕੋ ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਜੀਵਨ ਰਛਾ। ੩੫੪।","roman":"Khel dikhaavat hai jag ko ih hai kartaa sabh jeevan rachhaa | 354 |","meaning_en":"He shows his play to the world; he is the protector of all living beings.","page":389,"meaning_status":"draft"}]},{"type":"verse","number":[355],"number_text":"੩੫੫।","page":390,"lines":[{"gurmukhi":"ਆਇਸ ਮਾਨਿ ਸਭੈ ਮਘਵਾ ਹਰਿ ਕੇ ਪੁਰ ਘੇਰਿ ਘਨੇ ਘਨ ਗਾਜੈ।","roman":"Aais maani sabhai maghvaa hari ke pur gheri ghane ghan gaajai |","meaning_en":"Obeying Indra, all the dense clouds surrounded Hari's town and thundered.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਦਾਮਿਨਿ ਜਿਉ ਗਰਜੈ ਜਨੁ ਰਾਮ ਕੇ ਸਾਮੁਹਿ ਰਾਵਨ ਦੁੰਦਭਿ ਬਾਜੈ।","roman":"Daamini jiu garjai janu raam ke saamuhi raavan dundbhi baajai |","meaning_en":"The lightning crashed as though Ravan's kettledrums were beating before Ram.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਸੁਨਿ ਗੋਪ ਦਸੋ ਦਿਸ ਕੋ ਡਰ ਕੈ ਉਠਿ ਭਾਜੈ।","roman":"So dhuni sraunan mai suni gop daso dis ko dar kai uthi bhaajai |","meaning_en":"Hearing that sound in their ears, the cowherds rose and fled in fear in all ten directions.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਪਰੇ ਹਰਿ ਕੇ ਸਭ ਪਾਇਨ ਆਪਨ ਜੀਵ ਸਹਾਇਕ ਕਾਜੈ। ੩੫੫।","roman":"Aai pare hari ke sabh paain aapan jeev sahaaik kaajai | 355 |","meaning_en":"They all came and fell at Hari's feet, seeking help for their lives.","page":390,"meaning_status":"draft"}]},{"type":"verse","number":[356],"number_text":"੩੫੬।","page":390,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੋ ਡਰ ਕੈ ਹਰਿ ਸਾਮੁਹਿ ਗੋਪ ਪੁਕਾਰਤ ਹੈ ਦੁਖੁ ਮਾਝਾ।","roman":"Meghan ko dar kai hari saamuhi gop pukaarat hai dukhu maajhaa |","meaning_en":"Afraid of the clouds, the cowherds cry out before Hari in their distress:","page":390,"meaning_status":"draft","note":"ਮਾਝਾ: sense uncertain."},{"gurmukhi":"ਰਛ ਕਰੋ ਹਮਰੀ ਕਰੁਨਾਨਿਧਿ ਬ੍ਰਿਸਟ ਭਈ ਦਿਨ ਅਉ ਸਤ ਸਾਝਾ।","roman":"Rachh karo hamree karunaanidhi brisat bhaee din au sat saajhaa |","meaning_en":"'Protect us, treasure of mercy; it has rained for seven days and evenings.","page":390,"meaning_status":"draft","note":"ਦਿਨ ਅਉ ਸਤ ਸਾਝਾ: read as 'seven days and evenings'; uncertain."},{"gurmukhi":"ਏਕ ਬਚੀ ਨ ਗਊ ਪੁਰ ਕੀ ਮਰਗੀ ਦੁਧਰੀ ਬਛਰੇ ਅਰੁ ਬਾਝਾ।","roman":"Ek bachee na gaoo pur kee margee dudhree bachhre aru baajhaa |","meaning_en":"Not one cow of the town is left; milch cows, calves and barren cows have died.'","page":390,"meaning_status":"draft"},{"gurmukhi":"ਅਗ੍ਰਜ ਸ੍ਯਾਮ ਕੇ ਰੋਵਤ ਇਉ ਜਿਮ ਹੀਰ ਬਿਨਾ ਪਿਖਏ ਪਤਿ ਰਾਝਾ।੩੫੬।","roman":"Agraj syaam ke rovat iu jim heer binaa pikhae pati raajhaa | 356 |","meaning_en":"They weep before Shyam as Ranjha wept, the husband, unable to see Heer.","page":390,"meaning_status":"draft","note":"ਅਗ੍ਰਜ: read as 'before'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":390,"meaning_status":"draft"},{"type":"verse","number":[357],"number_text":"੩੫੭।","page":390,"lines":[{"gurmukhi":"ਕਾਲੀ ਨਾਥ ਕੇਸੀ ਰਿਪੁ ਕਉਲ ਨੈਨ ਕਉਲ ਨਾਭਿ","roman":"Kaalee naath kesee ripu kaul nain kaul naabhi","meaning_en":"'Tamer of Kali, enemy of Keshi, lotus-eyed, lotus-navelled,","page":390,"meaning_status":"draft","note":"Kali: the serpent Kaliya."},{"gurmukhi":"ਕਮਲਾ ਕੇ ਪਤਿ ਇਹ ਬਿਨਤੀ ਸੁਨੀਜੀਯੈ।","roman":"Kamlaa ke pati ih bintee suneejeeyai |","meaning_en":"husband of Kamla, hear this prayer.","page":390,"meaning_status":"draft","note":"Kamla: Lakshmi."},{"gurmukhi":"ਕਾਮ ਰੂਪ ਕੰਸ ਕੇ ਪ੍ਰਹਾਰੀ ਕਾਜਕਾਰੀ ਪ੍ਰਭ","roman":"Kaam roop kans ke prahaaree kaajkaaree prabh","meaning_en":"Beautiful as Love, slayer of Kans, Lord who accomplishes all tasks,","page":390,"meaning_status":"draft"},{"gurmukhi":"ਕਾਮਿਨੀ ਕੇ ਕਾਮ ਕੇ ਨਿਵਾਰੀ ਕਾਮ ਕੀਜੀਯੈ।","roman":"Kaaminee ke kaam ke nivaaree kaam keejeeyai |","meaning_en":"you who quench the desire of women, do this work for us.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਕਉਲਾਸਨ ਪਤਿ ਕੁੰਭਕਾਨ ਕੇ ਮਰਈਯਾ","roman":"Kaulaasan pati kunbhkaan ke maraeeyaa","meaning_en":"Lord of the one seated on the lotus, slayer of Kumbhkaran,","page":390,"meaning_status":"draft","note":"ਕਉਲਾਸਨ ਪਤਿ: read as lord of Lakshmi (or of Brahma, the lotus-seated); uncertain."},{"gurmukhi":"ਕਾਲਨੇਮਿ ਕੇ ਬਧਈਯਾ ਐਸੀ ਕੀਜੈ ਜਾ ਤੇ ਜੀਜੀਯੈ।","roman":"Kaalnemi ke badhaeeyaa aisee keejai jaa te jeejeeyai |","meaning_en":"slayer of Kalnemi, do something by which we may live.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਕਾਰਮਾ ਹਰਨ ਕਾਜ ਸਾਧਨ ਕਰਤ ਤੁਮ","roman":"Kaarmaa haran kaaj saadhan karat tum","meaning_en":"You remove our deeds and accomplish our tasks;","page":390,"meaning_status":"draft","note":"ਕਾਰਮਾ ਹਰਨ: read as 'remover of karma'; uncertain."},{"gurmukhi":"ਕ੍ਰਿਪਾ ਨਿਧਿ ਦਾਸਨ ਅਰਜ ਸੁਨਿ ਲੀਜੀਯੈ। ੩੫੭।","roman":"Kripaa nidhi daasan araj suni leejeeyai | 357 |","meaning_en":"treasure of mercy, hear the plea of your servants.'","page":390,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":390,"meaning_status":"draft"},{"type":"verse","number":[358],"number_text":"੩੫੮।","page":390,"lines":[{"gurmukhi":"ਬੂੰਦਨ ਤੀਰਨ ਸੀ ਸਭ ਹੀ ਕੁਪ ਕੈ ਬ੍ਰਿਜ ਕੇ ਪੁਰ ਪੈ ਜਬ ਪਈਯਾ।","roman":"Boondan teeran see sabh hee kup kai brij ke pur pai jab paeeyaa |","meaning_en":"When the drops, like arrows, fell in anger on the town of Braj,","page":390,"meaning_status":"draft"},{"gurmukhi":"ਸੋਊ ਸਹੀ ਨ ਗਈ ਕਿਹ ਪੈ ਸਭ ਧਾਮਨ ਬੇਧਿ ਧਰਾ ਲਗਿ ਗਈਯਾ।","roman":"So'oo sahee na gaee kih pai sabh dhaaman bedhi dharaa lagi gaeeyaa |","meaning_en":"no one could bear them; piercing all the houses, they struck the ground.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਪਿਖਿ ਗੋਪਨ ਨੈਨਨ ਸੋ ਬਿਨਤੀ ਹਰਿ ਕੇ ਅਗੂਆ ਪਹੁਚਈਯਾ।","roman":"So pikhi gopan nainan so bintee hari ke agooaa pahuchaeeyaa |","meaning_en":"Seeing this with their eyes, the cowherds brought their plea before Hari:","page":390,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪ ਭਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਹਮਰੀ ਤੁਮ ਰਛ ਕਰੋ ਉਠਿ ਸਈਯਾ। ੩੫੮।","roman":"Kop bhariyo ham pai maghvaa hamree tum rachh karo uthi saeeyaa | 358 |","meaning_en":"'Indra is full of anger against us; rise, Lord, and protect us.'","page":390,"meaning_status":"draft","note":"ਸਈਯਾ: read as 'Lord, master' (saeen); uncertain."}]},{"type":"verse","number":[359],"number_text":"੩੫੯।","page":390,"lines":[{"gurmukhi":"ਦੀਸਤ ਹੈ ਨ ਕਹੂੰ ਅਰਣੋਦਿਤ ਘੇਰਿ ਦਸੋ ਦਿਸ ਤੇ ਘਨ ਆਵੈ।","roman":"Deesat hai na kahoon arnodit gheri daso dis te ghan aavai |","meaning_en":"The dawn is nowhere to be seen; the clouds come, surrounding us from all ten directions.","page":390,"meaning_status":"draft","note":"ਅਰਣੋਦਿਤ: 'sunrise'."},{"gurmukhi":"ਕੋਪ ਭਰੇ ਜਨੁ ਕੇਹਰਿ ਗਾਜਤ ਦਾਮਿਨਿ ਦਾਤ ਨਿਕਾਸਿ ਡਰਾਵੈ।","roman":"Kop bhare janu kehri gaajat daamini daat nikaasi daraavai |","meaning_en":"Full of anger they roar like lions, and frighten us, baring the teeth of lightning.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਗੋਪਨ ਜਾਇ ਕਰੀ ਬਿਨਤੀ ਹਰਿ ਪੈ ਸੁਨੀਯੈ ਹਰਿ ਜੋ ਤੁਮ ਭਾਵੈ।","roman":"Gopan jaai karee bintee hari pai suneeyai hari jo tum bhaavai |","meaning_en":"The cowherds went and pleaded with Hari: 'Hear us, Hari, as it pleases you.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਘ ਕੇ ਦੇਖਤ ਸਿੰਘਨ ਸ੍ਯਾਰ ਕਹੈ ਕੁਪ ਕੈ ਜਮ ਲੋਕ ਪਠਾਵੈ। ੩੫੯।","roman":"Singh ke dekhat singhan syaar kahai kup kai jam lok pathaavai | 359 |","meaning_en":"Before the eyes of a lion, the jackal tells the lion's cubs he will angrily send them to Yama's world.'","page":390,"meaning_status":"draft","note":"Read as: Indra threatens us in your very presence; uncertain."}]},{"type":"verse","number":[360],"number_text":"੩੬੦।","page":390,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਹਮਰੇ ਪੁਰ ਮੈ ਬਹੁ ਮੇਘਨ ਕੇ ਇਹ ਠਾਟ ਠਟੇ।","roman":"Kop bhare hamre pur mai bahu meghan ke ih thaat thate |","meaning_en":"'Full of anger, the clouds have mustered in great array over our town.","page":390,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਕੋ ਗਜ ਬਾਹਨ ਲੋਕ ਕਹੈ ਜਿਨਿ ਪਬਨ ਕੇ ਪਰ ਕੋਪ ਕਟੇ।","roman":"Jih ko gaj baahan lok kahai jini paban ke par kop kate |","meaning_en":"He whom people call the one who rides the elephant, who in anger cut off the wings of the mountains:","page":390,"meaning_status":"draft","note":"Indra, rider of Airavat."},{"gurmukhi":"ਤੁਮ ਹੋ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੇ ਤੁਮ ਹੀ ਸਿਰ ਰਾਵਨ ਕਾਟਿ ਸਟੇ।","roman":"Tum ho kartaa sabh hee jag ke tum hee sir raavan kaati sate |","meaning_en":"you are the maker of the whole world; you cut off Ravan's heads and threw them down.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮ ਸਿਯੋ ਫੁਨਿ ਦੇਖਿਤ ਗੋਪਨ ਕੋ ਘਨ ਘੋਰਿ ਡਰਾਵਤ ਕੋਪ ਲਟੇ। ੩੬੦।","roman":"Tum siyo phuni dekhit gopan ko ghan ghori daraavat kop late | 360 |","meaning_en":"Even while you watch, the clouds thunder and terrify the cowherds in fury.'","page":391,"meaning_status":"draft","note":"ਕੋਪ ਲਟੇ: read as 'blazing with anger'; uncertain."}]},{"type":"verse","number":[361],"number_text":"੩੬੧।","page":391,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਡੋ ਸੁਨਿ ਲੋਕ ਤੁਮੈ ਫੁਨਿ ਜਾਮ ਸੁ ਜਾਪ ਕਰੈ ਤੁਹ ਆਠੋ।","roman":"Kaanh bado suni lok tumai phuni jaam su jaap karai tuh aatho |","meaning_en":"'Kanh, you are great; hear, people repeat your name all eight watches of the day.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਨੀਰ ਹੁਤਾਸਨ ਭੂਮਿ ਧਰਾਧਰ ਥਾਪਿ ਕਰਿਯੋ ਤੁਮ ਹੀ ਪ੍ਰਭ ਕਾਠੋ।","roman":"Neer hutaasan bhoomi dharaadhar thaapi kariyo tum hee prabh kaatho |","meaning_en":"Water, fire, earth and mountains: you alone, Lord, established and made firm.","page":391,"meaning_status":"draft","note":"ਕਾਠੋ: read as 'firm'; uncertain."},{"gurmukhi":"ਬੇਦ ਦਏ ਕਰ ਕੈ ਤੁਮ ਹੀ ਜਗ ਮੈ ਛਿਨ ਤਾਤ ਭਯੋ ਜਬ ਘਾਠੋ।","roman":"Bed dae kar kai tum hee jag mai chhin taat bhayo jab ghaatho |","meaning_en":"You gave the Vedas to the world when, in a moment, their father was in distress.","page":391,"meaning_status":"draft","note":"Second half sense uncertain; possibly Brahma's loss of the Vedas."},{"gurmukhi":"ਸਿੰਧੁ ਮਥਿਯੋ ਤੁਮ ਹੀ ਤ੍ਰੀਯ ਹ੍ਵੈ ਕਰਿ ਦੀਨ ਸੁਰਾਸੁਰ ਅਮ੍ਰਿਤ ਬਾਟੋ। ੩੬੧।","roman":"Sindhu mathiyo tum hee treey hvai kari deen suraasur amrit baato | 361 |","meaning_en":"You churned the ocean, and, taking a woman's form, shared out the nectar between gods and demons.'","page":391,"meaning_status":"draft","note":"Mohini form."}]},{"type":"verse","number":[362],"number_text":"੩੬੨।","page":391,"lines":[{"gurmukhi":"ਗੋਪਨ ਫੇਰਿ ਕਹੀ ਮੁਖਤੇ ਬਿਨੁ ਤੈ ਹਮਰੋ ਕੋਊ ਅਉਰ ਨ ਆਡਾ।","roman":"Gopan pheri kahee mukhte binu tai hamro ko'oo aur na aadaa |","meaning_en":"Again the cowherds said: 'Apart from you we have no other shield.","page":391,"meaning_status":"draft","note":"ਆਡਾ: 'shield, protection'."},{"gurmukhi":"ਮੇਘਨ ਮਾਰਿ ਬਿਥਾਰ ਡਰੋ ਕੁਪਿ ਬਾਲਕ ਮੂਰਤਿ ਜਿਉ ਤੁਮ ਗਾਡਾ।","roman":"Meghan maari bithaar daro kupi baalak moorti jiu tum gaadaa |","meaning_en":"In your anger kill the clouds and scatter them, as you crushed the cart when you were a child.","page":391,"meaning_status":"draft","note":"ਗਾਡਾ: read as 'cart' (the Shakat demon); uncertain."},{"gurmukhi":"ਮੇਘਨ ਕੋ ਪਿਖਿ ਰੂਪ ਭਯਾਨਕ ਬਹੁਤੁ ਡਰੈ ਫੁਨਿ ਜੀਉ ਅਸਾਡਾ।","roman":"Meghan ko pikhi roop bhayaanak bahutu darai phuni jeeu asaadaa |","meaning_en":"Seeing the fearsome form of the clouds, our hearts are very afraid.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਅਬੈ ਪੁਸਤੀਨ ਹ੍ਵੈ ਆਪ ਉਤਾਰ ਡਰੋ ਸਭ ਗੋਪਨ ਜਾਡਾ। ੩੬੨।","roman":"Kaanh abai pusteen hvai aap utaar daro sabh gopan jaadaa | 362 |","meaning_en":"Kanh, become now a fur coat yourself and take away the cold of all the cowherds.'","page":391,"meaning_status":"draft","note":"ਪੁਸਤੀਨ: Persian, 'fur coat'; ਜਾਡਾ: 'cold'."}]},{"type":"verse","number":[363],"number_text":"੩੬੩।","page":391,"lines":[{"gurmukhi":"ਆਇਸੁ ਪਾਇ ਪੁਰੰਦਰ ਕੋ ਘਨਘੋਰ ਘਟਾ ਚਹੂੰ ਓਰ ਤੇ ਆਵੈ।","roman":"Aaisu paai purandar ko ghanghor ghataa chahoon or te aavai |","meaning_en":"On Indra's order, dense dark masses of cloud come from all four sides.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਕਰ ਕ੍ਰੁਧ ਕਿਧੋ ਮਨ ਮਧਿ ਬ੍ਰਿਜ ਊਪਰ ਆਨ ਕੈ ਬਹੁ ਬਲ ਪਾਵੈ।","roman":"Kai kar krudh kidho man madhi brij oopar aan kai bahu bal paavai |","meaning_en":"With anger in their minds they come over Braj and use great force.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਅਉ ਅਤਿ ਹੀ ਚਪਲਾ ਚਮਕੈ ਬਹੁ ਬੂੰਦਨ ਤੀਰਨ ਸੀ ਬਰਖਾਵੈ।","roman":"Au ati hee chaplaa chamkai bahu boondan teeran see barkhaavai |","meaning_en":"And the lightning flashes fiercely, and many drops rain down like arrows.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਗੋਪ ਕਹੈ ਹਮ ਤੇ ਭਈ ਚੂਕ ਸੁ ਯਾ ਤੇ ਹਮੈ ਗਰਜੈ ਔ ਡਰਾਵੈ। ੩੬੩।","roman":"Gop kahai ham te bhaee chook su yaa te hamai garjai au daraavai | 363 |","meaning_en":"The cowherds say, 'We have made a mistake; that is why he thunders and frightens us.'","page":391,"meaning_status":"draft"}]},{"type":"verse","number":[364],"number_text":"੩੬੪।","page":391,"lines":[{"gurmukhi":"ਆਜ ਭਯੋ ਉਤਪਾਤ ਬਡੋ ਡਰੁ ਸਮਾਨਿ ਸਭੈ ਹਰਿ ਪਾਸ ਪੁਕਾਰੇ।","roman":"Aaj bhayo utpaat bado daru samaani sabhai hari paas pukaare |","meaning_en":"'Today a great calamity has come'; in fear they all cried out to Hari.","page":391,"meaning_status":"draft","note":"ਸਮਾਨਿ: sense uncertain."},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਤਿਹ ਤੇ ਬ੍ਰਿਜ ਪੈ ਬਰਖੇ ਘਨ ਭਾਰੇ।","roman":"Kop kariyo ham pai maghvaa tih te brij pai barkhe ghan bhaare |","meaning_en":"'Indra is angry with us; that is why heavy clouds rain on Braj.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਭਛਿ ਭਖਿਯੋ ਇਹ ਕੋ ਤੁਮ ਹੂ ਤਿਹ ਤੇ ਬ੍ਰਿਜ ਕੇ ਜਨ ਕੋਪਿ ਸੰਘਾਰੇ।","roman":"Bhachhi bhakhiyo ih ko tum hoo tih te brij ke jan kopi sanghaare |","meaning_en":"You ate his food, and so in his anger he destroys the people of Braj.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਰਛਕ ਹੋ ਸਭ ਹੀ ਜਗ ਕੇ ਤੁਮ ਰਛ ਕਰੋ ਹਮਰੀ ਰਖਵਾਰੇ। ੩੬੪।","roman":"Rachhak ho sabh hee jag ke tum rachh karo hamree rakhvaare | 364 |","meaning_en":"You are the protector of the whole world; protect us, O guardian.'","page":391,"meaning_status":"draft"}]},{"type":"verse","number":[365],"number_text":"੩੬੫।","page":391,"lines":[{"gurmukhi":"ਹੋਇ ਕ੍ਰਿਪਾਲ ਅਬੈ ਭਗਵਾਨ ਕ੍ਰਿਪਾ ਕਰਿ ਕੈ ਇਨ ਕੋ ਤੁਮ ਕਾਢੋ।","roman":"Hoi kripaal abai bhagvaan kripaa kari kai in ko tum kaadho |","meaning_en":"'Be merciful now, Lord, and in your mercy drive these off.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਦਿਨ ਸਾਤ ਇਹਾ ਬਰਖਿਯੋ ਘਨ ਗਾਢੋ।","roman":"Kop kariyo ham pai maghvaa din saat ihaa barkhiyo ghan gaadho |","meaning_en":"Indra is angry with us; for seven days the dense clouds have rained here.'","page":391,"meaning_status":"draft"},{"gurmukhi":"ਭ੍ਰਾਤ ਬਲੀ ਇਨਿ ਰਛਨ ਕੋ ਤਬ ਹੀ ਕਰਿ ਕੋਪ ਭਯੋ ਉਠਿ ਠਾਢੋ।","roman":"Bhraat balee ini rachhan ko tab hee kari kop bhayo uthi thaadho |","meaning_en":"Then the mighty brother rose and stood up in anger to protect them.","page":391,"meaning_status":"draft","note":"ਭ੍ਰਾਤ ਬਲੀ: read as Krishna, 'the mighty brother' (of Balram); uncertain."},{"gurmukhi":"ਜੀਵ ਗਯੋ ਘਟ ਮੇਘਨ ਕੋ ਸਭ ਗੋਪਨ ਕੇ ਮਨ ਆਨੰਦ ਬਾਢੋ। ੩੬੫।","roman":"Jeev gayo ghat meghan ko sabh gopan ke man aanand baadho | 365 |","meaning_en":"The life sank in the clouds, and joy grew in the hearts of all the cowherds.","page":391,"meaning_status":"draft","note":"ਜੀਵ ਗਯੋ ਘਟ: read as 'their spirit sank'; uncertain."}]},{"type":"verse","number":[366],"number_text":"੩੬੬।","page":391,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਸੁਨ ਕੈ ਬਿਨਤੀ ਹਰਿ ਗੋਪ ਸਭੈ ਅਪਨੇ ਕਰਿ ਜਾਣੇ।","roman":"Gopan kee sun kai bintee hari gop sabhai apne kari jaane |","meaning_en":"Hearing the cowherds' plea, Hari took all the cowherds as his own.","page":391,"meaning_status":"draft"},{"gurmukhi":"ਮੇਘਨ ਕੇ ਬਧਬੇ ਕਹੁ ਕਾਨ੍ਹ ਚਲਿਯੋ ਉਠਿ ਕੈ ਕਰਤਾ ਜੋਊ ਤਾਣੇ।","roman":"Meghan ke badhbe kahu kaanh chaliyo uthi kai kartaa jo'oo taane |","meaning_en":"Kanh rose and set out to destroy the clouds, he who is the creator of all.","page":391,"meaning_status":"draft","note":"ਤਾਣੇ: sense uncertain."},{"gurmukhi":"ਤਾ ਛਬਿ ਕੇ ਜਸ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪਨੇ ਮਨ ਮੈ ਪਹਿਚਾਣੇ।","roman":"Taa chhabi ke jas uch mahaa kabi ne apne man mai pahichaane |","meaning_en":"The poet recognised in his mind the high and great glory of that sight:","page":391,"meaning_status":"draft"},{"gurmukhi":"ਇਉ ਚਲ ਗਯੋ ਜਿਮ ਸਿੰਘ ਮ੍ਰਿਗੀ ਪਿਖਿ ਆਇ ਹੈ ਜਾਨ ਕਿਧੋ ਮੂਹਿ ਡਾਣੇ। ੩੬੬।","roman":"Iu chal gayo jim singh mrigee pikhi aai hai jaan kidho moohi daane | 366 |","meaning_en":"he went like a lion that sees a doe coming, as if it had come into its mouth.","page":391,"meaning_status":"draft","note":"ਮੂਹਿ ਡਾਣੇ: sense uncertain."}]},{"type":"verse","number":[367],"number_text":"੩੬੭।","page":392,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੇ ਬਧ ਕਾਜ ਚਲਿਯੋ ਭਗਵਾਨ ਕਿਧੋ ਰਸ ਭੀਤਰ ਰਤਾ।","roman":"Meghan ke badh kaaj chaliyo bhagvaan kidho ras bheetar rataa |","meaning_en":"The Lord went to destroy the clouds, as if steeped in passion.","page":392,"meaning_status":"draft","note":"ਰਸ: here read as the heroic mood; uncertain."},{"gurmukhi":"ਰਾਮ ਭਯੋ ਜੁਗ ਤੀਸਰ ਮਧਿ ਮਰਿਯੋ ਤਿਨ ਰਾਵਨ ਕੈ ਰਨ ਅਤਾ।","roman":"Raam bhayo jug teesar madhi mariyo tin raavan kai ran ataa |","meaning_en":"He became Ram in the third age and killed Ravan in the battle;","page":392,"meaning_status":"draft","note":"ਅਤਾ: sense uncertain."},{"gurmukhi":"ਅਉਧ ਕੇ ਬੀਚ ਬਧੂ ਬਰਬੇ ਕਹੁ ਕੋਪ ਕੈ ਬੈਲ ਨਥੇ ਜਿਹ ਸਤਾ।","roman":"Audh ke beech badhoo barbe kahu kop kai bail nathe jih sataa |","meaning_en":"in Avadh, to win a bride, he angrily yoked seven bulls;","page":392,"meaning_status":"draft","note":"Read as the yoking of seven bulls to win a bride (told of Krishna and Satya); uncertain."},{"gurmukhi":"ਗੋਪਨ ਗੋਧਨ ਰਛਨ ਕਾਜ ਤੁਰਿਯੋ ਤਿਹ ਕੋ ਗਜ ਜਿਉ ਮਦ ਮਤਾ। ੩੬੭।","roman":"Gopan godhan rachhan kaaj turiyo tih ko gaj jiu mad mataa | 367 |","meaning_en":"to protect the cowherds and their cattle, he dashed off like an elephant drunk in rut.","page":392,"meaning_status":"draft"}]},{"type":"verse","number":[368],"number_text":"੩੬੮।","page":392,"lines":[{"gurmukhi":"ਕਰਬੇ ਕਹੁ ਰਛ ਸੁ ਗੋਪਨ ਕੀ ਬਰ ਪੂਟ ਲਯੋ ਨਗ ਕੋ ਪਹਿ ਹਥਾ।","roman":"Karbe kahu rachh su gopan kee bar poot layo nag ko pahi hathaa |","meaning_en":"To protect the cowherds, he tore up the mountain by force with his hand.","page":392,"meaning_status":"draft"},{"gurmukhi":"ਤਨ ਕੋ ਨ ਕਰਿਯੋ ਬਲ ਰੰਚਕ ਤਾਹ ਕਰਿਯੋ ਜੁ ਹੁਤੋ ਕਰ ਬੀਚ ਜਥਾ।","roman":"Tan ko na kariyo bal ranchak taah kariyo ju huto kar beech jathaa |","meaning_en":"He did not use even a little of his body's strength; he held it as if it were already in his hand.","page":392,"meaning_status":"draft"},{"gurmukhi":"ਨ ਚਲੀ ਤਿਨ ਕੀ ਕਿਛੁ ਗੋਪਨ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਗਜ ਜਾਹਿ ਰਥਾ।","roman":"Na chalee tin kee kichhu gopan pai kabi syaam kahai gaj jaahi rathaa |","meaning_en":"Says the poet Shyam, the one whose chariot is an elephant could do nothing against the cowherds.","page":392,"meaning_status":"draft","note":"Indra, whose mount is the elephant."},{"gurmukhi":"ਮੁਖਿ ਨ੍ਯਾਇ ਖਿਸਾਇ ਚਲਿਯੋ ਗ੍ਰਿਹ ਪੈ ਇਹ ਬੀਚ ਚਲੀ ਜਗ ਕੇ ਸੁ ਕਥਾ।੩੬੮।","roman":"Mukhi nyaai khisaai chaliyo grih pai ih beech chalee jag ke su kathaa | 368 |","meaning_en":"Lowering his face in shame, he went home, and in the meantime the story spread through the world.","page":392,"meaning_status":"draft"}]},{"type":"verse","number":[369],"number_text":"੩੬੯।","page":392,"lines":[{"gurmukhi":"ਨੰਦ ਕੋ ਨੰਦ ਬਡੋ ਸੁਖ ਕੰਦ ਰਿਪੁ ਆਰ ਸੁਰੰਦ ਸਬੁਧਿ ਬਿਸਾਰਦ।","roman":"Nand ko nand bado sukh kand ripu aar surand sabudhi bisaarad |","meaning_en":"Nand's son, great, the source of joy, enemy of foes, lord of the gods, wise and learned,","page":392,"meaning_status":"draft","note":"ਰਿਪੁ ਆਰ ਸੁਰੰਦ: sense uncertain."},{"gurmukhi":"ਆਨਨ ਚੰਦ ਪ੍ਰਭਾ ਕਹੁ ਮੰਦ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਜਪੈ ਜਿਹ ਨਾਰਦ।","roman":"Aanan chand prabhaa kahu mand kahai kabi syaam japai jih naarad |","meaning_en":"whose face dims the light of the moon, says the poet Shyam, on whom Narad meditates,","page":392,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਗਿਰਿ ਕੋਪ ਉਠਾਇ ਲਯੋ ਜੋਊ ਸਾਧਨ ਕੋ ਹਰਤਾ ਦੁਖ ਦਾਰਦ।","roman":"Taa giri kop uthaai layo jo'oo saadhan ko hartaa dukh daarad |","meaning_en":"who removes the sorrow and poverty of the saints, lifted that mountain in his anger.","page":392,"meaning_status":"draft"},{"gurmukhi":"ਮੇਘ ਪਰੇ ਉਪਰਿਯੋ ਨ ਕਛੂ ਪਛਤਾਇ ਗਏ ਗ੍ਰਿਹ ਕੋ ਉਠਿ ਬਾਰਦ। ੩੬੯।","roman":"Megh pare upriyo na kachhoo pachhtaai gae grih ko uthi baarad | 369 |","meaning_en":"The clouds fell on it but nothing came of it; they repented, rose up and went home.","page":392,"meaning_status":"draft","note":"ਉਪਰਿਯੋ ਨ ਕਛੂ: read as 'nothing worked'; uncertain."}]},{"type":"verse","number":[370],"number_text":"੩੭੦।","page":392,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਉਪਾਰਿ ਲਯੋ ਕਰ ਮੋ ਗਿਰਿ ਏਕ ਪਰੀ ਨਹੀ ਬੂੰਦ ਸੁ ਪਾਨੀ।","roman":"Kaanh upaari layo kar mo giri ek paree nahee boond su paanee |","meaning_en":"Kanh uprooted the mountain in his hand, and not one drop of water fell.","page":392,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਹਸਿ ਕੈ ਮੁਖ ਤੇ ਹਰਿ ਕੋ ਮਘਵਾ ਜੁ ਭਯੋ ਮੁਹਿ ਸਾਨੀ।","roman":"Pheri kahee hasi kai mukh te hari ko maghvaa ju bhayo muhi saanee |","meaning_en":"Then Hari said, laughing: 'Indra would make himself my equal!","page":392,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਡਰਿਯੋ ਮੁਰ ਮੈ ਮਧੁ ਕੀਟਭ ਮਾਰਿਯੋ ਹਮੈ ਮਘਵਾ ਪਤਿ ਮਾਨੀ।","roman":"Maari dariyo mur mai madhu keetabh maariyo hamai maghvaa pati maanee |","meaning_en":"I killed Mur, and Madhu and Kaitabh; proud Indra thinks he can kill me?'","page":392,"meaning_status":"draft","note":"Second half sense uncertain."},{"gurmukhi":"ਗੋਪਨ ਮੈ ਭਗਵਾਨ ਕਹੀ ਸੋਊ ਫੈਲ ਪਰੀ ਜਗ ਬੀਚ ਕਹਾਨੀ। ੩੭੦।","roman":"Gopan mai bhagvaan kahee so'oo phail paree jag beech kahaanee | 370 |","meaning_en":"What the Lord said among the cowherds became a story that spread through the world.","page":392,"meaning_status":"draft"}]},{"type":"verse","number":[371],"number_text":"੩੭੧।","page":392,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਕਰਬੇ ਕਹੁ ਰਛ ਸਤਕ੍ਰਿਤ ਪੈ ਹਰਿ ਜੀ ਜਬ ਕੋਪੇ।","roman":"Gopan kee karbe kahu rachh satkrit pai hari jee jab kope |","meaning_en":"When Hari grew angry with Indra in order to protect the cowherds,","page":392,"meaning_status":"draft","note":"ਸਤਕ੍ਰਿਤ: Indra, 'of a hundred sacrifices'."},{"gurmukhi":"ਇਉ ਗਿਰਿ ਕੇ ਤਰਿ ਭਯੋ ਉਠਿ ਠਾਢਿ ਮਨੋ ਰੁਪ ਕੈ ਪਗ ਕੇਹਰਿ ਰੋਪੇ।","roman":"Iu giri ke tari bhayo uthi thaadhi mano rup kai pag kehri rope |","meaning_en":"he rose and stood beneath the mountain, as if a lion had planted its feet in fury;","page":392,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਜੁਗ ਅੰਤ ਮੈ ਅੰਤਕ ਹ੍ਵੈ ਕਰਿ ਜੀਵਨ ਕੇ ਸਭ ਕੇ ਉਰਿ ਘੋਪੇ।","roman":"Jiu jug ant mai antak hvai kari jeevan ke sabh ke uri ghope |","meaning_en":"as Death, at the end of the age, plunges into the hearts of all living beings;","page":392,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਜਨ ਕੋ ਮਨ ਹੋਤ ਹੈ ਲੋਪ ਤਿਸੀ ਬਿਧਿ ਮੇਘ ਭਏ ਸਭ ਲੋਪੇ। ੩੭੧।","roman":"Jiu jan ko man hot hai lop tisee bidhi megh bhae sabh lope | 371 |","meaning_en":"and as a person's mind fades away, in the same way all the clouds vanished.","page":392,"meaning_status":"draft"}]},{"type":"verse","number":[372],"number_text":"੩੭੨।","page":392,"lines":[{"gurmukhi":"ਹੋਇ ਸਤਕ੍ਰਿਤ ਊਪਰ ਕੋਪ ਸੁ ਰਾਖ ਲਈ ਸਭ ਗੋਪ ਦਫਾ।","roman":"Hoi satkrit oopar kop su raakh laee sabh gop daphaa |","meaning_en":"Angry with Indra, he saved the whole band of cowherds.","page":392,"meaning_status":"draft","note":"ਦਫਾ: read as 'group, band'; uncertain."},{"gurmukhi":"ਤਿਨਿ ਮੇਘ ਬਿਦਾਰ ਦਏ ਛਿਨ ਮੈ ਜਿਨਿ ਦੈਤ ਕਰੇ ਸਭ ਏਕ ਗਫਾ।","roman":"Tini megh bidaar dae chhin mai jini dait kare sabh ek gaphaa |","meaning_en":"He who made all the demons a single mouthful tore apart the clouds in a moment.","page":392,"meaning_status":"draft","note":"ਗਫਾ: read as 'mouthful'; uncertain."},{"gurmukhi":"ਕਰਿ ਕਉਤੁਕ ਪੈ ਰਿਪੁ ਟਾਰ ਦਏ ਬਿਨੁ ਹੀ ਧਰਏ ਸਰ ਸ੍ਯਾਮ ਜਫਾ।","roman":"Kari kautuk pai ripu taar dae binu hee dharae sar syaam japhaa |","meaning_en":"By his wonder he drove away the enemy, says Shyam, without even fitting an arrow to strike a blow.","page":392,"meaning_status":"draft","note":"ਜਫਾ: Persian 'injury, harm'; uncertain."},{"gurmukhi":"ਸਭ ਗੋਪਨ ਕੀ ਕਰਬੈ ਕਹੁ ਰਛ ਸੁ ਸਕ੍ਰਨ ਲੀਨ ਲਪੇਟ ਸਫਾ। ੩੭੨।","roman":"Sabh gopan kee karbai kahu rachh su sakran leen lapet saphaa | 372 |","meaning_en":"To protect all the cowherds, he rolled up Indra's array.","page":392,"meaning_status":"draft","note":"ਸਕ੍ਰਨ ... ਸਫਾ: read as 'Indra's ranks'; uncertain."}]},{"type":"verse","number":[373],"number_text":"੩੭੩।","page":392,"lines":[{"gurmukhi":"ਜੁ ਲਈ ਸਭ ਮੇਘ ਲਪੇਟ ਸਫਾ ਅਰੁ ਲੀਨੋ ਹੈ ਪਬ ਉਪਾਰ ਜਬੈ।","roman":"Ju laee sabh megh lapet saphaa aru leeno hai pab upaar jabai |","meaning_en":"When he had rolled up all the ranks of clouds and had uprooted the mountain,","page":392,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਰੰਚਕ ਸੋ ਇਹ ਹੈ ਗਰੂਓ ਗਿਰਿ ਚਿੰਤ ਕਰੀ ਮਨਿ ਬੀਚ ਸਬੈ।","roman":"Ih ranchak so ih hai garoo'o giri chint karee mani beech sabai |","meaning_en":"all thought in their minds: 'He is so small, and this mountain so heavy.","page":392,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਦੈਤਨ ਕੋ ਮਰਤਾ ਕਰਤਾ ਸੁਖ ਹੈ ਦਿਵਿਯਾ ਜੀਯ ਦਾਨ ਅਬੈ।","roman":"Ih daitan ko martaa kartaa sukh hai diviyaa jeey daan abai |","meaning_en":"He is the slayer of demons, the giver of joy; he has now given us the gift of life.","page":393,"meaning_status":"draft","note":"ਦਿਵਿਯਾ: read as 'has given'; uncertain."},{"gurmukhi":"ਇਹ ਕੋ ਤੁਮ ਧ੍ਯਾਨ ਧਰੋ ਸਭ ਹੀ ਨਹਿ ਧ੍ਯਾਨ ਧਰੋ ਤੁਮ ਅਉਰ ਕਬੈ।੩੭੩।","roman":"Ih ko tum dhyaan dharo sabh hee nahi dhyaan dharo tum aur kabai | 373 |","meaning_en":"Meditate on him, all of you, and never meditate on any other.'","page":393,"meaning_status":"draft"}]},{"type":"verse","number":[374],"number_text":"੩੭੪।","page":393,"lines":[{"gurmukhi":"ਸਭ ਮੇਘ ਗਏ ਘਟ ਕੇ ਜਬ ਹੀ ਤਬ ਹੀ ਹਰਖੇ ਫੁਨਿ ਗੋਪ ਸਭੈ।","roman":"Sabh megh gae ghat ke jab hee tab hee harkhe phuni gop sabhai |","meaning_en":"As soon as all the clouds had gone, all the cowherds rejoiced.","page":393,"meaning_status":"draft","note":"ਗਏ ਘਟ: read as 'faded away'."},{"gurmukhi":"ਇਹ ਭਾਤਿ ਲਗੇ ਕਹਨੇ ਮੁਖ ਤੇ ਭਗਵਾਨ ਦਯੋ ਹਮ ਦਾਨ ਅਭੈ।","roman":"Ih bhaati lage kahne mukh te bhagvaan dayo ham daan abhai |","meaning_en":"They began to say with their mouths: 'The Lord has given us the gift of fearlessness.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਮਘਵਾ ਜੁ ਕਰੀ ਕੁਪਿ ਦਉਰ ਹਮੂ ਪਰ ਸੋ ਤਿਹ ਕੋ ਨਹੀ ਬੇਰ ਲਭੈ।","roman":"Maghvaa ju karee kupi daur hamoo par so tih ko nahee ber labhai |","meaning_en":"The assault that Indra made on us in his anger took him no time at all to undo.","page":393,"meaning_status":"draft","note":"ਨਹੀ ਬੇਰ ਲਭੈ: sense uncertain."},{"gurmukhi":"ਅਬ ਕਾਨ੍ਹ ਪ੍ਰਤਾਪ ਤੇ ਹੈ ਘਟ ਬਾਦਰ ਏਕ ਨ ਦੀਸਤ ਬੀਚ ਨਭੈ। ੩੭੪।","roman":"Ab kaanh prataap te hai ghat baadar ek na deesat beech nabhai | 374 |","meaning_en":"Now, by Kanh's glory, the clouds have faded, and not one is seen in the sky.'","page":393,"meaning_status":"draft"}]},{"type":"verse","number":[375],"number_text":"੩੭੫।","page":393,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਸਭ ਹੀ ਮੁਖ ਤੇ ਇਹ ਕਾਨ੍ਹ ਬਲੀ ਬਰ ਹੈ ਬਲ ਮੈ।","roman":"Gop kahai sabh hee mukh te ih kaanh balee bar hai bal mai |","meaning_en":"All the cowherds say: 'This Kanh is mighty, foremost in strength.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨਿ ਕੂਦਿ ਕਿਲੇ ਸਤ ਮੋਰ ਮਰਿਯੋ ਜਿਨਿ ਜੁਧ ਸੰਖਾਸੁਰ ਸੋ ਜਲ ਮੈ।","roman":"Jini koodi kile sat mor mariyo jini judh sankhaasur so jal mai |","meaning_en":"He who leapt over the seven forts and killed Mur, who fought Sankhasur in the water.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਅਰੁ ਫੈਲ ਰਹਿਯੋ ਜਲ ਅਉ ਥਲ ਮੈ।","roman":"Ih hai kartaa sabh hee jag ko aru phail rahiyo jal au thal mai |","meaning_en":"He is the maker of the whole world, and pervades water and land.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਸੋਊ ਆਇ ਪ੍ਰਤਛਿ ਭਯੋ ਬ੍ਰਿਜ ਮੈ ਜੋਊ ਜੋਗ ਜੁਤੋ ਰਹੈ ਓਝਲ ਮੈ। ੩੭੫।","roman":"So'oo aai pratchhi bhayo brij mai jo'oo jog juto rahai ojhal mai | 375 |","meaning_en":"He has come and appeared openly in Braj, he who, joined in yoga, stays hidden.'","page":393,"meaning_status":"draft"}]},{"type":"verse","number":[376],"number_text":"੩੭੬।","page":393,"lines":[{"gurmukhi":"ਮੋਰ ਮਰਿਯੋ ਜਿਨਿ ਕੂਦ ਕਿਲੈ ਸਤ ਸੰਧਿ ਜਰਾ ਜਿਹ ਸੈਨ ਮਰੀ।","roman":"Mor mariyo jini kood kilai sat sandhi jaraa jih sain maree |","meaning_en":"He who leapt over the seven forts and killed Mur, by whom the army of Jarasandh was slain;","page":393,"meaning_status":"draft","note":"ਸੰਧਿ ਜਰਾ: Jarasandh."},{"gurmukhi":"ਨਰਾਕਸੁਰ ਜਾਹਿ ਕਰਿਯੋ ਰਕਸੀ ਬਿਰਥੀ ਗਜ ਕੀ ਜਿਹ ਰਛ ਕਰੀ।","roman":"Naraaksur jaahi kariyo raksee birthee gaj kee jih rachh karee |","meaning_en":"who destroyed Narakasur, who protected the elephant in its distress;","page":393,"meaning_status":"draft","note":"ਕਰਿਯੋ ਰਕਸੀ, ਬਿਰਥੀ: uncertain."},{"gurmukhi":"ਜਿਹ ਰਾਖਿ ਲਈ ਪਤਿ ਪੈ ਦ੍ਰੁਪਤੀ ਸਿਲ ਜਾ ਲਗਤਿਉ ਪਗ ਪਾਰਿ ਪਰੀ।","roman":"Jih raakhi laee pati pai druptee sil jaa lagtiu pag paari paree |","meaning_en":"who saved Draupadi's honour, and by the touch of whose foot the stone was carried across;","page":393,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"The stone: Ahalya."},{"gurmukhi":"ਅਤਿ ਕੋਪਤ ਮੇਘਨ ਅਉ ਮਘਵਾ ਇਹ ਰਾਖ ਲਈ ਨੰਦ ਲਾਲਿ ਧਰੀ।੩੭੬।","roman":"Ati kopat meghan au maghvaa ih raakh laee nand laali dharee | 376 |","meaning_en":"Nand's darling saved them from the furious clouds and Indra.","page":393,"meaning_status":"draft","note":"ਧਰੀ: sense uncertain."}]},{"type":"verse","number":[377],"number_text":"੩੭੭।","page":393,"lines":[{"gurmukhi":"ਮਘਵਾ ਜਿਹ ਫੇਰਿ ਦਈ ਪ੍ਰਤਨਾ ਜਿਹ ਦੈਤੁ ਮਰੇ ਇਹ ਕਾਨ ਬਲੀ।","roman":"Maghvaa jih pheri daee pratnaa jih daitu mare ih kaan balee |","meaning_en":"He who turned back Indra's army, by whom the demons were killed: this is mighty Kanh;","page":393,"meaning_status":"draft","note":"ਪ੍ਰਤਨਾ: read as 'army' (pritana)."},{"gurmukhi":"ਜਿਹ ਕੋ ਜਨ ਨਾਮ ਜਪੈ ਮਨ ਮੈ ਜਿਹ ਕੋ ਫੁਨਿ ਭ੍ਰਾਤ ਹੈ ਬੀਰ ਹਲੀ।","roman":"Jih ko jan naam japai man mai jih ko phuni bhraat hai beer halee |","meaning_en":"whose name people repeat in their hearts, whose brother is the hero Balram;","page":393,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਤੇ ਸਭ ਗੋਪਨ ਕੀ ਬਿਪਤਾ ਹਰਿ ਕੇ ਕੁਪ ਤੇ ਛਿਨ ਮਾਹਿ ਟਲੀ।","roman":"Jih te sabh gopan kee biptaa hari ke kup te chhin maahi talee |","meaning_en":"by whom, through Hari's anger, all the cowherds' trouble was averted in a moment.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਕੋ ਲਖ ਕੈ ਉਪਮਾ ਭਗਵਾਨ ਕਰੈ ਜਿਹ ਕੀ ਸੁਤ ਕਉਲ ਕਲੀ।੩੭੭।","roman":"Tih ko lakh kai upmaa bhagvaan karai jih kee sut kaul kalee | 377 |","meaning_en":"Seeing him, the Lord praises him, he whose son is the lotus-born.","page":393,"meaning_status":"draft","note":"Read as Vishnu, whose son is Brahma; line sense uncertain."}]},{"type":"verse","number":[378],"number_text":"੩੭੮।","page":393,"lines":[{"gurmukhi":"ਕਾਨ ਉਪਾਰ ਲਯੋ ਗਰੂਓ ਗਿਰਿ ਧਾਮਿ ਖਿਸਾਇ ਗਯੋ ਮਘਵਾ।","roman":"Kaan upaar layo garoo'o giri dhaami khisaai gayo maghvaa |","meaning_en":"Kanh uprooted the heavy mountain, and Indra went home abashed.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਉਪਜਿਯੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਜੋਊ ਤੀਸਰ ਜੁਗ ਭਯੋ ਰਘੁਵਾ।","roman":"So upjiyo brij bhoomi bikhai jo'oo teesar jug bhayo raghuvaa |","meaning_en":"He has been born in the land of Braj who in the third age was Raghu's descendant.","page":393,"meaning_status":"draft","note":"ਰਘੁਵਾ: Ram."},{"gurmukhi":"ਅਬ ਕਉਤੁਕਿ ਲੋਕ ਦਿਖਾਵਨ ਕੋ ਜਗ ਮੈ ਫੁਨਿ ਰੂਪ ਧਰਿਯੋ ਲਘੁਵਾ।","roman":"Ab kautuki lok dikhaavan ko jag mai phuni roop dhariyo laghuvaa |","meaning_en":"Now, to show the people his wonders, he has taken a small form in the world.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਥਨ ਐਚ ਹਨੀ ਛਿਨ ਮੈ ਪੁਤਨਾ ਹਰਿ ਨਾਮ ਕੇ ਲੇਤ ਹਰੇ ਅਘਵਾ। ੩੭੮।","roman":"Than aich hanee chhin mai putnaa hari naam ke let hare aghvaa | 378 |","meaning_en":"Pulling at her breast, he killed Putna in a moment; by taking Hari's name sins are removed.","page":393,"meaning_status":"draft"}]},{"type":"verse","number":[379],"number_text":"੩੭੯।","page":393,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਬ੍ਰਿਜ ਮੈ ਜਿਨਿ ਗੋਪਨ ਕੇ ਦੁਖ ਕਾਟਿ ਸਟੇ।","roman":"Kaanh balee pragtiyo brij mai jini gopan ke dukh kaati sate |","meaning_en":"Mighty Kanh has appeared in Braj, who has cut away and cast off the cowherds' sorrows.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਸੁਖ ਸਾਧਨ ਕੇ ਪ੍ਰਗਟੇ ਤਬ ਹੀ ਦੁਖ ਦੈਤਨ ਕੇ ਸੁਨਿ ਨਾਮੁ ਘਟੇ।","roman":"Sukh saadhan ke pragte tab hee dukh daitan ke suni naamu ghate |","meaning_en":"When he appeared, the joy of the saints appeared; hearing his name, the demons' sorrows grow.","page":393,"meaning_status":"draft","note":"ਘਟੇ: read as 'come over them'; uncertain."},{"gurmukhi":"ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਬਲਿ ਕੋ ਅਰੁ ਇੰਦ੍ਰਹਿ ਲੋਕ ਬਟੇ।","roman":"Ih hai kartaa sabh hee jag ko bali ko aru indrahi lok bate |","meaning_en":"He is the maker of the whole world, and divided the worlds between Bali and Indra.","page":393,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਨਾਮ ਕੇ ਲੇਤ ਕਿਧੋ ਮੁਖ ਤੇ ਲਟ ਜਾਤ ਸਭੈ ਤਨ ਦੋਖ ਲਟੇ। ੩੭੯।","roman":"Tih naam ke let kidho mukh te lat jaat sabhai tan dokh late | 379 |","meaning_en":"When one takes his name with the mouth, all the faults of the body are destroyed.","page":393,"meaning_status":"draft"}]},{"type":"verse","number":[380],"number_text":"੩੮੦।","page":394,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਪੁਤਨਾ ਜਿਨਿ ਮਾਰਿ ਡਰੀ ਨ੍ਰਿਪ ਕੰਸ ਪਠੀ।","roman":"Kaanh balee pragtiyo putnaa jini maari daree nrip kans pathee |","meaning_en":"Mighty Kanh has appeared, who killed Putna, sent by King Kans.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਇਨ ਹੀ ਰਿਪੁ ਮਾਰਿ ਡਰਿਯੋ ਸੁ ਤ੍ਰਿਨਾਵ੍ਰਤ ਪੈ ਜਨਿ ਸੋ ਇਹ ਥਿਤ ਛਠੀ।","roman":"In hee ripu maari dariyo su trinaavrat pai jani so ih thit chhathee |","meaning_en":"He killed the enemy Trinavrat, as if that were the sixth-day festival.","page":394,"meaning_status":"draft","note":"ਥਿਤ ਛਠੀ: read as the sixth-day rite after birth; uncertain."},{"gurmukhi":"ਸਭ ਜਾਪੁ ਜਪੈ ਇਹ ਕੋ ਮਨ ਮੈ ਸਭ ਗੋਪ ਕਹੈ ਇਹ ਅਤਿ ਹਠੀ।","roman":"Sabh jaapu japai ih ko man mai sabh gop kahai ih ati hathee |","meaning_en":"All repeat his name in their hearts; all the cowherds say he is very resolute.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਹੀ ਪ੍ਰਤਿਨਾ ਫੁਨਿ ਮੇਘਨ ਕੀ ਇਨਹੂ ਕਰਿ ਦੀ ਛਿਨ ਮਾਹਿ ਮਠੀ।੩੮੦।","roman":"Ati hee pratinaa phuni meghan kee inhoo kari dee chhin maahi mathee | 380 |","meaning_en":"He crushed the mighty army of the clouds in a moment.","page":394,"meaning_status":"draft","note":"ਮਠੀ: read as 'crushed'; uncertain."}]},{"type":"verse","number":[381],"number_text":"੩੮੧।","page":394,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਇਹ ਸਾਧਨ ਕੇ ਦੁਖ ਦੂਰਿ ਕਰੈ ਮਨ ਮਾਹਿ ਗਡੈ।","roman":"Gop kahai ih saadhan ke dukh doori karai man maahi gadai |","meaning_en":"The cowherds say: 'He removes the sorrows of the saints and is fixed in their hearts.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਹੈ ਬਲਵਾਨ ਬਡੋ ਪ੍ਰਗਟਿਯੋ ਸੋਊ ਕੋ ਇਹ ਸੋ ਛਿਨ ਆਇ ਅਡੈ।","roman":"Ih hai balvaan bado pragtiyo so'oo ko ih so chhin aai adai |","meaning_en":"He has appeared as one very mighty; who could stand against him for a moment?","page":394,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਲੋਕ ਕਹੈ ਫੁਨਿ ਜਾਪਤ ਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਬਡੈ।","roman":"Sabh lok kahai phuni jaapat yaa kabi syaam kahai bhagvaan badai |","meaning_en":"All people repeat his name,' says the poet Shyam, 'he is the great Lord.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਮੋਛ ਲਹੀ ਛਿਨ ਮੈ ਇਹ ਤੇ ਜਿਨ ਕੇ ਮਨ ਮੈ ਜਰਰਾ ਕੁ ਜਡੈ। ੩੮੧।","roman":"Tin mochh lahee chhin mai ih te jin ke man mai jarraa ku jadai | 381 |","meaning_en":"Those in whose hearts he is set even a particle obtain liberation through him in a moment.'","page":394,"meaning_status":"draft","note":"ਜਰਰਾ: Persian 'a particle'."}]},{"type":"verse","number":[382],"number_text":"੩੮੨।","page":394,"lines":[{"gurmukhi":"ਮੇਘ ਗਏ ਪਛੁਤਾਇ ਗ੍ਰਿਹੰ ਕਹੁ ਗੋਪਿਨ ਕੋ ਮਨ ਆਨੰਦ ਬਾਢੇ।","roman":"Megh gae pachhutaai grihan kahu gopin ko man aanand baadhe |","meaning_en":"The clouds went home repenting, and joy grew in the hearts of the cowherds.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਹ੍ਵੈ ਇਕਠੇ ਸੁ ਚਲੇ ਗ੍ਰਿਹ ਕੋ ਸਭ ਆਇ ਭਏ ਗ੍ਰਿਹ ਭੀਤਰ ਠਾਢੇ।","roman":"Hvai ikthe su chale grih ko sabh aai bhae grih bheetar thaadhe |","meaning_en":"Together they went home, and all came and stood inside their houses.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਲਗੇ ਕਹਿਨੇ ਤ੍ਰੀਯ ਸੋ ਇਨ ਹੀ ਛਿਨ ਮੈ ਮਘਵਾ ਕੁਪਿ ਕਾਢੇ।","roman":"Aai lage kahine treey so in hee chhin mai maghvaa kupi kaadhe |","meaning_en":"They came and began to tell their wives: 'He drove away angry Indra in a moment.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਲਹਿਯੋ ਭਗਵਾਨ ਹਮੈ ਇਨ ਹੀ ਹਮਰੇ ਸਭ ਹੀ ਦੁਖ ਕਾਢੇ। ੩੮੨।","roman":"Sati lahiyo bhagvaan hamai in hee hamre sabh hee dukh kaadhe | 382 |","meaning_en":"We have known him truly as the Lord; he has taken away all our sorrows.'","page":394,"meaning_status":"draft"}]},{"type":"verse","number":[383],"number_text":"੩੮੩।","page":394,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਪਤਿ ਲੋਕਹ ਕੇ ਦਲ ਆਬ ਰਖੇ ਠਟਿ ਸਾਜ ਅਣੇ।","roman":"Kop bhare pati lokah ke dal aab rakhe thati saaj ane |","meaning_en":"The angry lord of the worlds had brought hosts laden with water, arrayed and equipped.","page":394,"meaning_status":"draft","note":"Indra; ਆਬ: Persian 'water'."},{"gurmukhi":"ਭਗਵਾਨ ਜੂ ਠਾਢ ਭਯੋ ਕਰਿ ਲੈ ਗਿਰਿ ਪੈ ਕਰਿ ਕੈ ਕੁਛ ਹੂੰ ਨ ਗਣੇ।","roman":"Bhagvaan joo thaadh bhayo kari lai giri pai kari kai kuchh hoon na gane |","meaning_en":"The Lord stood holding the mountain in his hand and counted it as nothing.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਤਾ ਛਬਿ ਕੇ ਜਸ ਉਚ ਮਹਾ ਕਬਿ ਸ੍ਯਾਮ ਕਿਧੌ ਇਹ ਭਾਤਿ ਭਣੇ।","roman":"Ati taa chhabi ke jas uch mahaa kabi syaam kidhau ih bhaati bhane |","meaning_en":"The poet Shyam told the high and great glory of that sight in this way:","page":394,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮੁ ਬੀਰ ਬਡੋ ਕਰਿ ਸਿਪਰ ਲੈ ਕਛੁ ਕੈ ਨ ਗਨੇ ਪੁਨਿ ਤੀਰ ਘਣੇ। ੩੮੩।","roman":"Jimu beer bado kari sipar lai kachhu kai na gane puni teer ghane | 383 |","meaning_en":"as a great warrior takes a shield in his hand and cares nothing for a hail of arrows.","page":394,"meaning_status":"draft","note":"ਸਿਪਰ: Persian 'shield'."}]},{"type":"verse","number":[384],"number_text":"੩੮੪।","page":394,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਇਹ ਸਾਧਨ ਕੋ ਦੁਖ ਦੂਰ ਕਰੈ ਮਨ ਮਾਹਿ ਗਡੈ।","roman":"Gop kahai ih saadhan ko dukh door karai man maahi gadai |","meaning_en":"The cowherds say: 'He removes the sorrow of the saints and is fixed in their hearts.","page":394,"meaning_status":"draft","note":"Verse repeats 24.53 with small changes."},{"gurmukhi":"ਇਹ ਹੈ ਬਲਵਾਨ ਬਡੋ ਪ੍ਰਗਟਿਓ ਸੋਊ ਕੋ ਇਹ ਸੋ ਛਿਨ ਆਇ ਅਡੈ।","roman":"Ih hai balvaan bado pragtio so'oo ko ih so chhin aai adai |","meaning_en":"He has appeared as one very mighty; who could stand against him for a moment?","page":394,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਲੋਗ ਕਹੈ ਫੁਨਿ ਖਾਪਤ ਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਬਡੈ।","roman":"Sabh log kahai phuni khaapat yaa kabi syaam kahai bhagvaan badai |","meaning_en":"All people repeat his name,' says the poet Shyam, 'he is the great Lord.","page":394,"meaning_status":"draft","note":"ਖਾਪਤ: printed so; read as 'jaapat', repeat."},{"gurmukhi":"ਤਿਹ ਮੋਛ ਲਹੀ ਛਿਨ ਮੈ ਇਹ ਤੇ ਜਿਨ ਕੇ ਮਨ ਮੈ ਜਰਰਾ ਕੁ ਜਡੈ। ੩੮੪।","roman":"Tih mochh lahee chhin mai ih te jin ke man mai jarraa ku jadai | 384 |","meaning_en":"Those in whose hearts he is set even a particle obtain liberation through him in a moment.'","page":394,"meaning_status":"draft"}]},{"type":"verse","number":[385],"number_text":"੩੮੫।","page":394,"lines":[{"gurmukhi":"ਕਰਿ ਕੋਪ ਨਿਵਾਰ ਦਏ ਮਘਵਾ ਦਲ ਕਾਨ ਬਡੇ ਬਲਬੀਰ ਬ੍ਰਤੀ।","roman":"Kari kop nivaar dae maghvaa dal kaan bade balbeer bratee |","meaning_en":"In anger Kanh, the great mighty hero true to his vow, drove off Indra's forces,","page":394,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਕੋਪਿ ਜਲੰਧਰਿ ਈਸਿ ਮਰਿਯੋ ਜਿਮ ਚੰਡਿ ਚਮੁੰਡਹਿ ਸੈਨ ਹਤੀ।","roman":"Jim kopi jalandhri eesi mariyo jim chandi chamundhi sain hatee |","meaning_en":"as Shiva in his anger killed Jalandhar, and as Chandi and Chamunda destroyed the armies.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਪਛੁਤਾਇ ਗਯੋ ਮਘਵਾ ਗ੍ਰਿਹ ਕੋ ਨ ਰਹੀ ਤਿਹ ਕੀ ਪਤਿ ਏਕ ਰਤੀ।","roman":"Pachhutaai gayo maghvaa grih ko na rahee tih kee pati ek ratee |","meaning_en":"Indra went home repenting; not a jot of his honour remained.","page":394,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਮੇਘ ਬਿਦਾਰ ਦਏ ਹਰਿ ਜੀ ਜਿਮ ਮੋਹਿ ਨਿਵਾਰਤ ਕੋਪਿ ਜਤੀ। ੩੮੫।","roman":"Ik megh bidaar dae hari jee jim mohi nivaarat kopi jatee | 385 |","meaning_en":"Hari tore apart every cloud, as an ascetic angrily drives out delusion.","page":394,"meaning_status":"draft","note":"ਇਕ: read as 'every one'; uncertain."}]},{"type":"verse","number":[386],"number_text":"੩੮੬।","page":395,"lines":[{"gurmukhi":"ਕੁਪ ਕੈ ਤਿਨਿ ਮੇਘ ਬਿਦਾਰ ਦਏ ਜਿਨਿ ਰਾਖ ਲਯੋ ਜਲ ਭੀਤਰ ਹਾਥੀ।","roman":"Kup kai tini megh bidaar dae jini raakh layo jal bheetar haathee |","meaning_en":"In his anger he tore the clouds apart, he who saved the elephant in the water;","page":395,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹਿ ਸਿਲਾ ਲਗਿ ਪਾਇ ਤਰੀ ਜਿਹ ਰਾਖਿ ਲਈ ਦ੍ਰੁਪਤੀ ਸੁ ਅਨਾਥੀ।","roman":"Jaahi silaa lagi paai taree jih raakhi laee druptee su anaathee |","meaning_en":"touching whose feet the stone was saved, who saved helpless Draupadi.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਬੈਰ ਕਰੈ ਜੋਊ ਪੈ ਇਹ ਸੋ ਸਭ ਗੋਪ ਕਹੈ ਇਹ ਤਾਹਿ ਅਸਾਥੀ।","roman":"Bair karai jo'oo pai ih so sabh gop kahai ih taahi asaathee |","meaning_en":"All the cowherds say: 'Whoever bears enmity to him, he is no companion to him.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਹਿਤ ਸੋ ਚਿਤ ਕੈ ਇਹ ਕੀ ਫੁਨਿ ਸੇਵ ਕਰੈ ਤਿਹ ਕੋ ਇਹ ਸਾਥੀ। ੩੮੬।","roman":"Jo hit so chit kai ih kee phuni sev karai tih ko ih saathee | 386 |","meaning_en":"But whoever serves him lovingly with heart and mind, to him he is a companion.'","page":395,"meaning_status":"draft"}]},{"type":"verse","number":[387],"number_text":"੩੮੭।","page":395,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੋ ਤਬ ਹੀ ਕ੍ਰਿਸਨੰ ਦਲ ਖਾਤਿਰ ਊਪਰਿ ਨ ਕਛੂ ਆਂਦਾ।","roman":"Meghan ko tab hee krisnan dal khaatir oopri na kachhoo aandaa |","meaning_en":"Then Krishna paid no heed at all to the host of clouds.","page":395,"meaning_status":"draft","note":"ਖਾਤਿਰ: Persian 'regard'; read as 'paid no heed'; uncertain."},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਅਤਿ ਹੀ ਮਘਵਾ ਨ ਚਲਿਯੋ ਤਿਹ ਸੋ ਕਛੁ ਤਾਹਿ ਬਸਾਂਦਾ।","roman":"Kop kariyo ati hee maghvaa na chaliyo tih so kachhu taahi basaandaa |","meaning_en":"Indra was very angry, but nothing he did had any effect against him.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰ ਚਲੈ ਕਿਹ ਕੋ ਤਿਹ ਸੋ ਕਹਿ ਹੈ ਸਭ ਹੀ ਜਿਸ ਕੋ ਜਗੁ ਬਾਂਦਾ।","roman":"Jor chalai kih ko tih so kahi hai sabh hee jis ko jagu baandaa |","meaning_en":"Whose strength can prevail against him, they all say, whom the whole world serves?","page":395,"meaning_status":"draft","note":"ਬਾਂਦਾ: Persian 'servant, bondsman'."},{"gurmukhi":"ਮੂੰਡ ਨਿਵਾਇ ਮਨੈ ਦੁਖ ਪਾਇ ਗਯੋ ਮਘਵਾ ਉਠਿ ਧਾਮਿ ਖਿਸਾਂਦਾ। ੩੮੭।","roman":"Moond nivaai manai dukh paai gayo maghvaa uthi dhaami khisaandaa | 387 |","meaning_en":"Bowing his head, grieved in his heart, Indra rose and went home abashed.","page":395,"meaning_status":"draft"}]},{"type":"verse","number":[388],"number_text":"੩੮੮।","page":395,"lines":[{"gurmukhi":"ਸਕ੍ਰ ਗਯੋ ਪਛੁਤਾਹਿ ਗ੍ਰਿਹੰ ਕਹੁ ਫੋਰ ਦਈ ਜਬ ਕਾਨ੍ਹਿ ਅਨੀ।","roman":"Sakr gayo pachhutaahi grihan kahu phor daee jab kaanhi anee |","meaning_en":"Indra went home repenting when Kanh had shattered his army.","page":395,"meaning_status":"draft","note":"ਸਕ੍ਰ: Indra; ਅਨੀ: 'army'."},{"gurmukhi":"ਬਰਖਾ ਕਰਿ ਕੋਪ ਕਰੀ ਬ੍ਰਿਜ ਪੈ ਸੁ ਕਛੂ ਹਰਿ ਕੈ ਨਹਿ ਏਕ ਗਨੀ।","roman":"Barkhaa kari kop karee brij pai su kachhoo hari kai nahi ek ganee |","meaning_en":"He rained in anger on Braj, but Hari counted it as nothing.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਫੁਨਿ ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਸ੍ਯਾਮ ਕਿਧੋ ਇਹ ਭਾਤਿ ਭਨੀ।","roman":"Phuni taa chhabi kee ati hee upmaa kabi syaam kidho ih bhaati bhanee |","meaning_en":"The poet Shyam then told the great beauty of that sight in this way:","page":395,"meaning_status":"draft"},{"gurmukhi":"ਪਛਤਾਇ ਗਯੋ ਪਤਿ ਲੋਕਨ ਕੋ ਜਿਮ ਲੂਟ ਲਯੋ ਅਹਿ ਸੀਸ ਮਨੀ। ੩੮੮।","roman":"Pachhtaai gayo pati lokan ko jim loot layo ahi sees manee | 388 |","meaning_en":"the lord of the worlds went away repenting, like a snake robbed of the jewel on its head.","page":395,"meaning_status":"draft"}]},{"type":"verse","number":[389],"number_text":"੩੮੯।","page":395,"lines":[{"gurmukhi":"ਜਾਹਿ ਨ ਜਾਨਤ ਭੇਦ ਮੁਨੀ ਮਨਿ ਭਾ ਇਹ ਜਾਪਨ ਕੋ ਇਹ ਜਾਪੀ।","roman":"Jaahi na jaanat bhed munee mani bhaa ih jaapan ko ih jaapee |","meaning_en":"He whose secret even the sages do not know, he is the one to be meditated on and the one who meditates.","page":395,"meaning_status":"draft","note":"ਮਨਿ ਭਾ: sense uncertain."},{"gurmukhi":"ਰਾਜ ਦਯੋ ਇਨ ਹੀ ਬਲਿ ਕੋ ਇਨ ਹੀ ਕਬਿ ਸ੍ਯਾਮ ਧਰਾ ਸਭ ਥਾਪੀ।","roman":"Raaj dayo in hee bali ko in hee kabi syaam dharaa sabh thaapee |","meaning_en":"He gave Bali his kingdom; he, says the poet Shyam, established the whole earth.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਤ ਹੈ ਦਿਨ ਥੋਰਨ ਮੈ ਰਿਪੁ ਗੋਪ ਕਹੈ ਇਹ ਕਾਨ ਪ੍ਰਤਾਪੀ।","roman":"Maarat hai din thoran mai ripu gop kahai ih kaan prataapee |","meaning_en":"'In a few days he will kill the enemy,' say the cowherds; 'this Kanh is glorious.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਕਾਰਨ ਯਾਹਿ ਧਰੀ ਇਹ ਮੂਰਤਿ ਮਾਰਨ ਕੋ ਜਗ ਕੇ ਸਭ ਪਾਪੀ। ੩੮੯।","roman":"Kaaran yaahi dharee ih moorti maaran ko jag ke sabh paapee | 389 |","meaning_en":"For this reason he took this form: to kill all the sinners of the world.'","page":395,"meaning_status":"draft"}]},{"type":"verse","number":[390],"number_text":"੩੯੦।","page":395,"lines":[{"gurmukhi":"ਕਰਿ ਕੈ ਜਿਹ ਸੋ ਛਲ ਪੈ ਚਤੁਰਾਨਨ ਚੋਰਿ ਲਏ ਸਭ ਗੋਪ ਦਫਾ।","roman":"Kari kai jih so chhal pai chaturaanan chori lae sabh gop daphaa |","meaning_en":"He with whom the four-faced Brahma played a trick, stealing away all the cowherd band,","page":395,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕਉਤਕ ਦੇਖਨ ਕਾਰਨ ਕੋ ਫੁਨਿ ਰਾਖਿ ਰਹਿਓ ਵਹ ਬੀਚ ਖਫਾ।","roman":"Tin kautak dekhan kaaran ko phuni raakhi rahio vah beech khaphaa |","meaning_en":"and who, to see the wonder, kept them hidden away in displeasure:","page":395,"meaning_status":"draft","note":"ਖਫਾ: Persian 'displeased'; line sense uncertain."},{"gurmukhi":"ਕਾਨ ਬਿਨਾ ਕੁਪਏ ਉਹ ਸੋ ਸੁ ਕਰੇ ਬਿਨ ਹੀ ਸਰ ਦੀਨ ਜਫਾ।","roman":"Kaan binaa kupae uh so su kare bin hee sar deen japhaa |","meaning_en":"Kanh, without anger towards him, and without shooting an arrow, did him harm;","page":395,"meaning_status":"draft","note":"ਜਫਾ: Persian 'harm, injury'; uncertain."},{"gurmukhi":"ਛਿਨ ਮਧਿ ਬਨਾਇ ਲਏ ਬਛਰੇ ਸਭ ਗੋਪਨ ਕੀ ਉਨ ਹੀ ਸੀ ਸਫਾ। ੩੯੦।","roman":"Chhin madhi banaai lae bachhre sabh gopan kee un hee see saphaa | 390 |","meaning_en":"in a moment he made all the calves and the cowherds' ranks exactly like them.","page":395,"meaning_status":"draft"}]},{"type":"verse","number":[391],"number_text":"੩੯੧।","page":395,"lines":[{"gurmukhi":"ਕਾਨ ਉਪਾਰਿ ਧਰਿਓ ਕਰ ਪੈ ਗਿਰਿ ਤਾ ਤਰਿ ਗੋਪ ਨਿਕਾਰਿ ਸਬੈ।","roman":"Kaan upaari dhario kar pai giri taa tari gop nikaari sabai |","meaning_en":"Kanh uprooted the mountain, held it on his hand, and brought all the cowherds out from under it.","page":395,"meaning_status":"draft"},{"gurmukhi":"ਬਕਈ ਬਕ ਅਉਰ ਗਡਾਸੁਰ ਤ੍ਰਿਨਾਵ੍ਰਤ ਬੀਰ ਬਧੇ ਛਿਨ ਬੀਚ ਤਬੈ।","roman":"Bakaee bak aur gadaasur trinaavrat beer badhe chhin beech tabai |","meaning_en":"Bakai, Bak and Gadasur, and the warrior Trinavrat, he slew in a moment then.","page":395,"meaning_status":"draft","note":"Bakai: Putna; Gadasur: the cart demon."},{"gurmukhi":"ਜਿਨ ਕਾਲੀ ਕੋ ਨਾਥ ਲਯੋ ਛਿਨ ਭੀਤਰ ਧਿਆਨ ਨ ਛਾਡਹੁ ਵਾਹਿ ਕਬੈ।","roman":"Jin kaalee ko naath layo chhin bheetar dhiaan na chhaadhu vaahi kabai |","meaning_en":"He who put a nose-string on Kali in a moment: never leave off meditating on him.","page":395,"meaning_status":"draft","note":"Kali: the serpent Kaliya."},{"gurmukhi":"ਸਭ ਸੰਤ ਸੁਨੀ ਸੁਭ ਕਾਨ੍ਹ ਕਥਾ ਇਕ ਅਉਰ ਕਥਾ ਸੁਨਿ ਲੇਹੁ ਅਬੈ। ੩੯੧।","roman":"Sabh sant sunee subh kaanh kathaa ik aur kathaa suni lehu abai | 391 |","meaning_en":"All you saints have heard the good story of Kanh; now hear one more story.","page":395,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪ ਬਾਚ ਨੰਦ ਜੂ ਸੋ","gurmukhi":"ਗੋਪ ਬਾਚ ਨੰਦ ਜੂ ਸੋ","roman":"Gop baach nand joo so","meaning_en":"The cowherds said to Nand:","page":396,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":396,"meaning_status":"draft"},{"type":"verse","number":[392],"number_text":"੩੯੨।","page":396,"lines":[{"gurmukhi":"ਨੰਦ ਕੇ ਅਗ੍ਰਜ ਕਾਨ੍ਹ ਪਰਾਕ੍ਰਮ ਗੋਪਨ ਜਾਇ ਕਹਿਯੋ ਸੁ ਸਬੈ।","roman":"Nand ke agraj kaanh paraakram gopan jaai kahiyo su sabai |","meaning_en":"The cowherds went before Nand and told him all of Kanh's valour:","page":396,"meaning_status":"draft","note":"ਅਗ੍ਰਜ: read as 'before'."},{"gurmukhi":"ਦੈਤ ਅਘਾਸੁਰ ਅਉਰ ਤ੍ਰਿਨਾਵ੍ਰਤ ਯਾਹਿ ਬਧਿਯੋ ਉਡਿ ਬੀਚ ਨਭੈ।","roman":"Dait aghaasur aur trinaavrat yaahi badhiyo udi beech nabhai |","meaning_en":"'He killed the demon Aghasur, and Trinavrat, flying up into the sky;","page":396,"meaning_status":"draft"},{"gurmukhi":"ਫੁਨਿ ਮਾਰਿ ਡਰੀ ਬਕਈ ਸਭ ਗੋਪਨ ਦਾਨ ਦਯੋ ਇਹ ਕਾਨ੍ਹ ਅਭੈ।","roman":"Phuni maari daree bakaee sabh gopan daan dayo ih kaanh abhai |","meaning_en":"then he killed Bakai; this Kanh has given all the cowherds the gift of fearlessness.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨੀਐ ਪਤਿ ਕੋਟਿ ਉਪਾਵ ਕਰੋ ਕੋਊ ਪੈ ਇਹ ਸੋ ਸੁਤ ਨਾਹਿ ਨਭੈ। ੩੯੨।","roman":"Suneeai pati koti upaav karo ko'oo pai ih so sut naahi nabhai | 392 |","meaning_en":"Listen, chief: make countless efforts, yet no one will have a son like this, nor has under heaven.'","page":396,"meaning_status":"draft","note":"ਨਾਹਿ ਨਭੈ: sense uncertain."}]},{"type":"verse","number":[393],"number_text":"੩੯੩।","page":396,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਬਿਨਤੀ ਸੁਨੀਐ ਪਤਿ ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਰਣਗਾਮੀ।","roman":"Gopan kee bintee suneeai pati dhiaan dharai ih ko rangaamee |","meaning_en":"'Hear the cowherds' plea, chief: warriors who go to battle meditate on him.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਮੁਨਿ ਈਸਰ ਧਿਆਨ ਧਰੈ ਇਹ ਕਾਇਰ ਕਾਮੀ।","roman":"Dhiaan dharai ih ko muni eesar dhiaan dharai ih kaair kaamee |","meaning_en":"The great sages meditate on him; cowards and lustful men meditate on him.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਸੁ ਤ੍ਰਿਯਾ ਸਭ ਧਿਆਨ ਧਰੈ ਇਹ ਦੇਖਨ ਬਾਮੀ।","roman":"Dhiaan dharai ih ko su triyaa sabh dhiaan dharai ih dekhan baamee |","meaning_en":"All good women meditate on him; women meditate on seeing him.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਲਖਿਯੋ ਹਮ ਕੈ ਕਰਤਾ ਜਗ ਸਤਿ ਕਹਿਯੋ ਮਤ ਕੈ ਨਹਿ ਖਾਮੀ। ੩੯੩।","roman":"Sati lakhiyo ham kai kartaa jag sati kahiyo mat kai nahi khaamee | 393 |","meaning_en":"We have truly known him as the creator of the world; we have spoken the truth, without fault in our understanding.'","page":396,"meaning_status":"draft","note":"ਖਾਮੀ: Persian 'fault, defect'."}]},{"type":"verse","number":[394],"number_text":"੩੯੪।","page":396,"lines":[{"gurmukhi":"ਹੈ ਭਗਵਾਨ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਸਭ ਗੋਪ ਕਹੈ ਪੁਤਨਾ ਇਨ ਮਾਰੀ।","roman":"Hai bhagvaan balee pragtiyo sabh gop kahai putnaa in maaree |","meaning_en":"'He is the mighty Lord made manifest,' say all the cowherds; 'he killed Putna.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਬਿਭੀਛਨ ਯਾਹਿ ਦਯੋ ਇਨ ਹੀ ਕੁਪਿ ਰਾਵਨ ਦੈਤ ਸੰਘਾਰੀ।","roman":"Raaj bibheechhan yaahi dayo in hee kupi raavan dait sanghaaree |","meaning_en":"He gave the kingdom to Bibhichhan; he in his anger destroyed the demon Ravan.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਰਛ ਕਰੀ ਪ੍ਰਲਾਦਹਿ ਕੀ ਇਨ ਹੀ ਹਰਨਾਖਸ ਕੀ ਉਰ ਫਾਰੀ।","roman":"Rachh karee pralaadhi kee in hee harnaakhas kee ur phaaree |","meaning_en":"He protected Prahlad; he tore open the chest of Harnakhas.","page":396,"meaning_status":"draft","note":"Harnakhas: Hiranyakashipu."},{"gurmukhi":"ਨੰਦ ਸੁਨੋ ਪਤਿ ਲੋਕਨ ਕੈ ਇਨ ਹੀ ਹਮਰੀ ਅਬ ਦੇਹ ਉਬਾਰੀ। ੩੯੪।","roman":"Nand suno pati lokan kai in hee hamree ab deh ubaaree | 394 |","meaning_en":"Listen, Nand, he is the lord of the worlds; he has now saved our lives.'","page":396,"meaning_status":"draft"}]},{"type":"verse","number":[395],"number_text":"੩੯੫।","page":396,"lines":[{"gurmukhi":"ਹੈ ਸਭ ਲੋਗਨ ਕੋ ਕਰਤਾ ਬ੍ਰਿਜ ਭੀਤਰ ਹੈ ਕਰਤਾ ਇਹ ਲੀਲਾ।","roman":"Hai sabh logan ko kartaa brij bheetar hai kartaa ih leelaa |","meaning_en":"'He is the maker of all people; in Braj he is performing this play.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਸਿਖ੍ਯਨ ਕੋ ਬਰਤਾ ਹਰਿ ਹੈ ਇਹ ਸਾਧਨ ਕੋ ਹਰਤਾ ਤਨ ਹੀਲਾ।","roman":"Sikhyan ko bartaa hari hai ih saadhan ko hartaa tan heelaa |","meaning_en":"Hari is the giver of boons to disciples, and he removes the bodily distress of the saints.","page":396,"meaning_status":"draft","note":"ਹੀਲਾ: read as 'trouble, distress'; uncertain."},{"gurmukhi":"ਰਾਖ ਲਈ ਇਨ ਹੀ ਸੀਅ ਕੀ ਪਤਿ ਰਾਖਿ ਲਈ ਤ੍ਰਿਯ ਪਾਰਥ ਸੀਲਾ।","roman":"Raakh laee in hee seea kee pati raakhi laee triy paarath seelaa |","meaning_en":"He saved Sita's honour; he saved the modesty of Arjun's wife.","page":396,"meaning_status":"draft","note":"Arjun's wife: Draupadi."},{"gurmukhi":"ਗੋਪ ਕਹੈ ਪਤਿ ਸੋ ਸੁਨੀਐ ਇਹ ਹੈ ਕ੍ਰਿਸਨੰ ਬਰ ਬੀਰ ਹਠੀਲਾ। ੩੯੫।","roman":"Gop kahai pati so suneeai ih hai krisnan bar beer hatheelaa | 395 |","meaning_en":"The cowherds say to their chief, 'Listen, this Krishna is a great and steadfast hero.'","page":396,"meaning_status":"draft"}]},{"type":"verse","number":[396],"number_text":"੩੯੬।","page":396,"lines":[{"gurmukhi":"ਦਿਨ ਬੀਤ ਗਏ ਚਕਏ ਗਿਰਿ ਕੇ ਹਰਿ ਜੀ ਬਛਰੇ ਸੰਗ ਲੈ ਬਨਿ ਜਾਵੈ।","roman":"Din beet gae chakae giri ke hari jee bachhre sang lai bani jaavai |","meaning_en":"Days passed after the mountain amazed them, and Hari goes to the forest taking the calves.","page":396,"meaning_status":"draft","note":"ਚਕਏ ਗਿਰਿ ਕੇ: sense uncertain."},{"gurmukhi":"ਜਿਉ ਧਰ ਮੂਰਤਿ ਘਾਸੁ ਚੁਗੈ ਭਗਵਾਨ ਮਹਾ ਮਨ ਮੈ ਸੁਖ ਪਾਵੈ।","roman":"Jiu dhar moorti ghaasu chugai bhagvaan mahaa man mai sukh paavai |","meaning_en":"As they graze on grass, the Lord, taking his form among them, finds great joy in his heart.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਮੁਰਲੀ ਅਪੁਨੇ ਕਰ ਮੈ ਕਰਿ ਭਾਵ ਘਨੇ ਹਿਤ ਸਾਥ ਬਜਾਵੈ।","roman":"Lai murlee apune kar mai kari bhaav ghane hit saath bajaavai |","meaning_en":"Taking the flute in his hand, he plays it lovingly, with many moods.","page":396,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿ ਰਹੈ ਜੁ ਸੁਨੈ ਪਤਨੀ ਸੁਰ ਮੋਹਿ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ। ੩੯੬।","roman":"Mohi rahai ju sunai patnee sur mohi rahai dhuni jo suni paavai | 396 |","meaning_en":"The wives of the gods who hear it are enchanted; whoever gets to hear the sound is enchanted.","page":396,"meaning_status":"draft"}]},{"type":"verse","number":[397],"number_text":"੩੯੭।","page":396,"lines":[{"gurmukhi":"ਕੁਪ ਕੈ ਜਿਨਿ ਬਾਲਿ ਮਰਿਓ ਛਿਨ ਮੈ ਅਰੁ ਰਾਵਨ ਕੀ ਜਿਨਿ ਸੈਨ ਮਰੀ ਹੈ।","roman":"Kup kai jini baali mario chhin mai aru raavan kee jini sain maree hai |","meaning_en":"He who in anger killed Bali in a moment and destroyed the army of Ravan,","page":396,"meaning_status":"draft","note":"ਬਾਲਿ: Bali the monkey king."},{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਰਾਜ ਦਯੋ ਛਿਨ ਮੈ ਜਿਹ ਕੀ ਤਿਹ ਲੰਕ ਕਰੀ ਹੈ।","roman":"Jaahi bibheechhan raaj dayo chhin mai jih kee tih lank karee hai |","meaning_en":"who gave Bibhichhan the kingdom in a moment and made Lanka his,","page":396,"meaning_status":"draft"},{"gurmukhi":"ਮੁਰ ਮਾਰਿ ਦਯੋ ਘਟਿਕਾਨ ਕਰੀ ਰਿਪੁ ਜਾ ਸੀਅ ਕੀ ਜੀਯ ਪੀਰ ਹਰੀ ਹੈ।","roman":"Mur maari dayo ghatikaan karee ripu jaa seea kee jeey peer haree hai |","meaning_en":"who killed Mur and cut Ghatika down, and removed the pain in Sita's heart:","page":396,"meaning_status":"draft","note":"ਘਟਿਕਾਨ ਕਰੀ: sense uncertain."},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਭਗਵਾਨ ਸੁ ਗਊਅਨ ਕੈ ਮਿਸ ਖੇਲ ਕਰੀ ਹੈ। ੩੯੭।","roman":"So brij bhoomi bikhai bhagvaan su gaooan kai mis khel karee hai | 397 |","meaning_en":"that Lord, in the land of Braj, has made play on the pretext of the cows.","page":396,"meaning_status":"draft"}]},{"type":"verse","number":[398],"number_text":"੩੯੮।","page":397,"lines":[{"gurmukhi":"ਜਾਹਿ ਸਹੰਸ੍ਰ ਫਨੀ ਤਨ ਊਪਰਿ ਸੋਇ ਕਰੀ ਜਲ ਭੀਤਰ ਕ੍ਰੀੜਾ।","roman":"Jaahi sahansr phanee tan oopri soi karee jal bheetar kreeraa |","meaning_en":"He who sleeps on the body of the thousand-hooded serpent and sports in the waters;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਰਾਜ ਦਯੋ ਅਰੁ ਜਾਹਿ ਦਈ ਕੁਪਿ ਰਾਵਨ ਪੀੜਾ।","roman":"Jaahi bibheechhan raaj dayo aru jaahi daee kupi raavan peeraa |","meaning_en":"who gave the kingdom to Bibhichhan and who in anger gave Ravan pain;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹਿ ਦਯੋ ਕਰ ਕੈ ਜਗ ਭੀਤਰ ਜੀਵ ਚਰਾਚਰ ਅਉ ਗਜ ਕੀੜਾ।","roman":"Jaahi dayo kar kai jag bheetar jeev charaachar au gaj keeraa |","meaning_en":"who made and gave life in the world to all beings, moving and unmoving, elephant and insect;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲਤ ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਜਿਨਿ ਕੀਲ ਸੁਰਾਸੁਰ ਬੀਚ ਝਗੀੜਾ। ੩੯੮।","roman":"Khelat so brij bhoomi bikhai jini keel suraasur beech jhageeraa | 398 |","meaning_en":"who stilled the quarrel between gods and demons: he plays in the land of Braj.","page":397,"meaning_status":"draft","note":"ਕੀਲ: read as 'stilled, pinned down'; uncertain."}]},{"type":"verse","number":[399],"number_text":"੩੯੯।","page":397,"lines":[{"gurmukhi":"ਬੀਰ ਬਡੇ ਦੁਰਜੋਧਨ ਆਦਿਕ ਜਾਹਿ ਮਰਾਇ ਡਰੇ ਰਨਿ ਛਤ੍ਰੀ।","roman":"Beer bade durjodhan aadik jaahi maraai dare rani chhatree |","meaning_en":"He by whom great warriors like Duryodhan, Kshatriyas, were made to die in battle;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹਿ ਮਰਿਯੋ ਸਿਸੁਪਾਲ ਰਿਸੈ ਕਰਿ ਰਾਜਨ ਮੈ ਕ੍ਰਿਸਨੰ ਬਰ ਅਤ੍ਰੀ।","roman":"Jaahi mariyo sisupaal risai kari raajan mai krisnan bar atree |","meaning_en":"who angrily killed Sisupal among the kings: that is Krishna, the great warrior.","page":397,"meaning_status":"draft","note":"ਅਤ੍ਰੀ: read as 'warrior, wielder of weapons'; uncertain."},{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਗਊਅਨ ਮੈ ਜੋਊ ਹੈ ਜਗ ਕੋ ਕਰਤਾ ਬਧ ਸਤ੍ਰੀ।","roman":"Khelat hai so'oo gaooan mai jo'oo hai jag ko kartaa badh satree |","meaning_en":"He plays among the cows, he who is the maker of the world and slayer of enemies.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਆਗਿ ਸੋ ਧੂਮ੍ਰ ਲਪੇਟਤ ਜਿਉ ਫੁਨਿ ਗੋਪ ਕਹਾਵਤ ਹੈ ਇਹ ਛਤ੍ਰੀ। ੩੯੯।","roman":"Aagi so dhoomr lapetat jiu phuni gop kahaavat hai ih chhatree | 399 |","meaning_en":"As fire is wrapped in smoke, so this Kshatriya is called a cowherd.","page":397,"meaning_status":"draft"}]},{"type":"verse","number":[400],"number_text":"੪੦੦।","page":397,"lines":[{"gurmukhi":"ਕਰ ਜੁਧ ਮਰੇ ਇਕਲੇ ਮਧੁ ਕੀਟਭ ਰਾਜੁ ਸਤਕ੍ਰਿਤ ਕੋ ਜਿਹ ਦੀਆ।","roman":"Kar judh mare ikle madhu keetabh raaju satkrit ko jih deeaa |","meaning_en":"He who fought alone and killed Madhu and Kaitabh, and gave Indra his kingdom;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਕੁੰਭਕਰਨ ਮਰਿਯੋ ਜਿਨਿ ਹੈ ਅਰੁ ਰਾਵਨ ਕੋ ਛਿਨ ਮੈ ਬਧ ਕੀਆ।","roman":"Kunbhakran mariyo jini hai aru raavan ko chhin mai badh keeaa |","meaning_en":"who killed Kumbhkaran and slew Ravan in a moment;","page":397,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜੁ ਬਿਭੀਛਨ ਦੇ ਕਰਿ ਆਨੰਦ ਅਉਧਿ ਚਲਿਯੋ ਸੰਗਿ ਲੈ ਕਰਿ ਸੀਆ।","roman":"Raaju bibheechhan de kari aanand audhi chaliyo sangi lai kari seeaa |","meaning_en":"who gave the kingdom to Bibhichhan and went joyfully to Avadh, taking Sita with him:","page":397,"meaning_status":"draft"},{"gurmukhi":"ਪਾਪਨ ਕੇ ਬਧ ਕਾਰਨ ਸੋ ਅਵਤਾਰ ਬਿਖੈ ਬ੍ਰਿਜ ਕੇ ਅਬ ਲੀਆ। ੪੦੦।","roman":"Paapan ke badh kaaran so avtaar bikhai brij ke ab leeaa | 400 |","meaning_en":"he has now taken avatar in Braj in order to slay the sinners.","page":397,"meaning_status":"draft"}]},{"type":"verse","number":[401],"number_text":"੪੦੧।","page":397,"lines":[{"gurmukhi":"ਜੋ ਉਪਮਾ ਹਰਿ ਕੀ ਕਰੀ ਗੋਪਨ ਤਉ ਪਤਿ ਗੋਪਨ ਬਾਤ ਕਹੀ ਹੈ।","roman":"Jo upmaa hari kee karee gopan tau pati gopan baat kahee hai |","meaning_en":"When the cowherds praised Hari, the chief of the cowherds spoke:","page":397,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਇਹ ਕੋ ਬਲੁ ਆਇ ਕਹਿਯੋ ਗਰਗੈ ਹਮ ਸੋ ਸੋਊ ਬਾਤ ਸਹੀ ਹੈ।","roman":"Jo ih ko balu aai kahiyo gargai ham so so'oo baat sahee hai |","meaning_en":"'What Garg came and told us of his strength is true.","page":397,"meaning_status":"draft","note":"Garg: the sage who named Krishna."},{"gurmukhi":"ਪੂਤੁ ਕਹਿਯੋ ਬਸੁਦੇਵਹਿ ਕੋ ਦਿਜ ਤਾਹਿ ਮਿਲਿਯੋ ਫੁਨਿ ਮਾਨਿ ਇਹੀ ਹੈ।","roman":"Pootu kahiyo basudevhi ko dij taahi miliyo phuni maani ihee hai |","meaning_en":"The Brahmin told me he was Basudev's son; I met him and accepted this.","page":397,"meaning_status":"draft","note":"Basudev: Vasudev."},{"gurmukhi":"ਜੋ ਇਹ ਕੋ ਫੁਨਿ ਮਾਰਨ ਆਯੋ ਸੁ ਤਾਹੀ ਕੀ ਦੇਹ ਗਈ ਨ ਰਹੀ ਹੈ। ੪੦੧।","roman":"Jo ih ko phuni maaran aayo su taahee kee deh gaee na rahee hai | 401 |","meaning_en":"Whoever came to kill him, his own body was gone and did not remain.'","page":397,"meaning_status":"draft"}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਇੰਦ੍ਰ ਆਇ ਦਰਸਨ ਕੀਆ ਅਰੁ ਬੇਨਤੀ ਕਰਤ ਭਯਾ","gurmukhi":"ਅਥ ਇੰਦ੍ਰ ਆਇ ਦਰਸਨ ਕੀਆ ਅਰੁ ਬੇਨਤੀ ਕਰਤ ਭਯਾ","roman":"Ath indr aai darsan keeaa aru bentee karat bhayaa","meaning_en":"Now Indra came, had sight of him, and made his prayer.","page":397,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":397,"meaning_status":"draft"},{"type":"verse","number":[402],"number_text":"੪੦੨।","page":397,"lines":[{"gurmukhi":"ਦਿਨ ਏਕ ਗਏ ਬਨ ਕੋ ਹਰਿ ਜੀ ਮਘਵਾ ਤਜਿ ਮਾਨ ਹਰੀ ਪਹਿ ਆਯੋ।","roman":"Din ek gae ban ko hari jee maghvaa taji maan haree pahi aayo |","meaning_en":"One day, when Hari had gone to the forest, Indra put aside his pride and came to Hari.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਪਾਪਨ ਕੇ ਬਖਸਾਵਨ ਕੋ ਹਰਿ ਕੇ ਤਰਿ ਪਾਇਨ ਸੀਸ ਨਿਵਾਯੋ।","roman":"Paapan ke bakhsaavan ko hari ke tari paain sees nivaayo |","meaning_en":"To have his sins forgiven, he bowed his head at Hari's feet.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਕਰੀ ਬਿਨਤੀ ਹਰਿ ਕੀ ਅਤਿ ਹੀ ਤਿਹ ਤੋ ਭਗਵਾਨ ਰਿਝਾਯੋ।","roman":"Aur karee bintee hari kee ati hee tih to bhagvaan rijhaayo |","meaning_en":"And he made many prayers to Hari, and so he pleased the Lord.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਚੂਕ ਭਈ ਹਮ ਤੇ ਕਹਿਯੋ ਸਕ੍ਰ ਸੁ ਕੈ ਹਰਿ ਜੀ ਤੁਮ ਕੌ ਨਹਿ ਪਾਯੋ। ੪੦੨।","roman":"Chook bhaee ham te kahiyo sakr su kai hari jee tum kau nahi paayo | 402 |","meaning_en":"'I have made a mistake,' said Indra, 'for I did not recognise you, Hari.'","page":397,"meaning_status":"draft"}]},{"type":"verse","number":[403],"number_text":"੪੦੩।","page":397,"lines":[{"gurmukhi":"ਤੂ ਜਗ ਕੋ ਕਰਤਾ ਕਰੁਨਾਨਿਧਿ ਤੂ ਸਭ ਲੋਗਨ ਕੋ ਕਰਤਾ ਹੈ।","roman":"Too jag ko kartaa karunaanidhi too sabh logan ko kartaa hai |","meaning_en":"'You are the creator of the world, treasure of mercy; you are the maker of all people.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਤੂ ਮੁਰ ਕੋ ਮਰੀਯਾ ਰਿਪੁ ਰਾਵਨ ਭੂਰਿਸਿਲਾ ਤ੍ਰੀਯਾ ਕੋ ਭਰਤਾ ਹੈ।","roman":"Too mur ko mareeyaa ripu raavan bhoorisilaa treeyaa ko bhartaa hai |","meaning_en":"You are the slayer of Mur, the enemy of Ravan, the husband of Bhurishila's [unclear] woman.","page":397,"meaning_status":"draft","note":"ਭੂਰਿਸਿਲਾ ਤ੍ਰੀਯਾ ਕੋ ਭਰਤਾ: sense unclear; possibly 'husband of the woman of the earth (Sita) / Lakshmi'. Very uncertain."},{"gurmukhi":"ਤੂ ਸਭ ਦੇਵਨ ਕੋ ਪਤਿ ਹੈ ਅਰੁ ਸਾਧਨ ਕੇ ਦੁਖ ਕੋ ਹਰਤਾ ਹੈ।","roman":"Too sabh devan ko pati hai aru saadhan ke dukh ko hartaa hai |","meaning_en":"You are the lord of all the gods and the remover of the sorrows of the saints.","page":397,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਤੁਮਰੀ ਕਛੁ ਭੂਲ ਕਰੈ ਤਿਹ ਕੇ ਫੁਨਿ ਤੂ ਤਨ ਕੋ ਮਰਤਾ ਹੈ। ੪੦੩।","roman":"Jo tumree kachhu bhool karai tih ke phuni too tan ko martaa hai | 403 |","meaning_en":"Whoever wrongs you in any way, you are the destroyer of his body.'","page":397,"meaning_status":"draft"}]},{"type":"verse","number":[404],"number_text":"੪੦੪।","page":398,"lines":[{"gurmukhi":"ਸੁਨਿ ਕਾਨ੍ਹ ਸਤਕ੍ਰਿਤ ਕੀ ਉਪਮਾ ਤਬ ਕਾਮ ਸੁ ਧੇਨ ਗਊ ਚਲਿ ਆਈ।","roman":"Suni kaanh satkrit kee upmaa tab kaam su dhen gaoo chali aaee |","meaning_en":"Hearing Indra praise Kanh, Kamdhenu, the wish-granting cow, came there.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਕਰੀ ਉਪਮਾ ਹਰਿ ਕੀ ਬਹੁ ਭਾਤਿਨ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਬਡਾਈ।","roman":"Aai karee upmaa hari kee bahu bhaatin so kabi syaam badaaee |","meaning_en":"She came and praised Hari greatly in many ways, says the poet Shyam.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਹੀ ਗੁਨ ਕਾਨਰ ਕੇ ਇਕ ਕਿੰਕਰ ਆਇ ਗਈ ਹਰਿ ਪਾਈ।","roman":"Gaavat hee gun kaanar ke ik kinkar aai gaee hari paaee |","meaning_en":"While she sang Kanh's praises, a handmaid came to Hari's feet.","page":398,"meaning_status":"draft","note":"ਕਿੰਕਰ: 'servant'; who this is is unclear."},{"gurmukhi":"ਸ੍ਯਾਮ ਕਰੋ ਉਪਮਾ ਕਹਿਯੋ ਪਤਿ ਸੋ ਉਪਮਾ ਬਹੁ ਭਾਤਿਨ ਭਾਈ। ੪੦੪।","roman":"Syaam karo upmaa kahiyo pati so upmaa bahu bhaatin bhaaee | 404 |","meaning_en":"'Shyam, sing his praise,' her lord said; and the praise pleased him in many ways.","page":398,"meaning_status":"draft","note":"Line sense uncertain."}]},{"type":"verse","number":[405],"number_text":"੪੦੫।","page":398,"lines":[{"gurmukhi":"ਕਾਨਰ ਕੇ ਪਗ ਪੂਜਨ ਕੋ ਸਭ ਦੇਵਪੁਰੀ ਤਜਿ ਕੈ ਸੁਰ ਆਏ।","roman":"Kaanar ke pag poojan ko sabh devpuree taji kai sur aae |","meaning_en":"To worship Kanh's feet, all the gods left the city of the gods and came.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇ ਪਰੇ ਇਕ ਪੂਜਤ ਭੇ ਇਕ ਨਾਚ ਉਠੇ ਇਕ ਮੰਗਲ ਗਾਏ।","roman":"Paai pare ik poojat bhe ik naach uthe ik mangal gaae |","meaning_en":"Some fell at his feet, some worshipped, some began to dance, some sang songs of joy.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਸੇਵ ਕਰੈ ਹਰਿ ਕੀ ਹਿਤ ਕੈ ਕਰਿ ਆਵਤ ਕੇਸਰ ਧੂਪ ਜਗਾਏ।","roman":"Sev karai hari kee hit kai kari aavat kesar dhoop jagaae |","meaning_en":"They serve Hari lovingly, bringing saffron and lighting incense.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਦੈਤਨ ਕੋ ਬਧ ਕੈ ਭਗਵਾਨ ਮਨੋ ਜਗ ਮੈ ਸੁਰ ਫੇਰਿ ਬਸਾਏ। ੪੦੫।","roman":"Daitan ko badh kai bhagvaan mano jag mai sur pheri basaae | 405 |","meaning_en":"It was as if the Lord, having slain the demons, had settled the gods in the world again.","page":398,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":398,"meaning_status":"draft"},{"type":"verse","number":[406],"number_text":"੪੦੬।","page":398,"lines":[{"gurmukhi":"ਦੇਵ ਸਕ੍ਰ ਆਦਿਕ ਸਭੈ ਸਭ ਤਜਿ ਕੈ ਮਨਿ ਮਾਨ।","roman":"Dev sakr aadik sabhai sabh taji kai mani maan |","meaning_en":"All the gods, Indra and the rest, putting away all pride from their minds,","page":398,"meaning_status":"draft"},{"gurmukhi":"ਹ੍ਵੈ ਇਕਤ੍ਰ ਕਰਨੈ ਲਗੇ ਕ੍ਰਿਸਨ ਉਸਤਤੀ ਬਾਨਿ। ੪੦੬।","roman":"Hvai ikatr karnai lage krisan usattee baani | 406 |","meaning_en":"gathered together and began to sing words of praise to Krishna.","page":398,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":398,"meaning_status":"draft"},{"type":"verse","number":[407],"number_text":"੪੦੭।","page":398,"lines":[{"gurmukhi":"ਪ੍ਰੇਮ ਭਰੇ ਲਾਜ ਕੇ ਜਹਾਜ ਦੋਊ ਦੇਖੀਅਤ ਬਾਰਿ ਭਰੇ ਅਭ੍ਰਨ ਕੀ ਆਭਾ ਕੋ ਧਰਤ ਹੈ।","roman":"Prem bhare laaj ke jahaaj do'oo dekheeat baari bhare abhran kee aabhaa ko dharat hai |","meaning_en":"Both his eyes are seen full of love, ships of modesty, bearing the glow of water-laden clouds.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਸੀਲ ਕੇ ਹੈ ਸਿੰਧੁ ਗੁਨ ਸਾਗਰ ਉਜਾਗਰ ਕੇ ਨਾਗਰ ਨਵਲ ਨੈਨ ਦੋਖਨ ਹਰਤ ਹੈ।","roman":"Seel ke hai sindhu gun saagar ujaagar ke naagar naval nain dokhan harat hai |","meaning_en":"They are oceans of good nature, seas of virtue, bright, refined and fresh; his eyes remove faults.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰਨ ਸੰਘਾਰੀ ਇਹ ਕਾਨ੍ਹ ਅਵਤਾਰੀ ਜੂ ਕੇ ਸਾਧਨ ਕੋ ਦੇਹ ਦੂਖ ਦੂਰ ਕੋ ਕਰਤ ਹੈ।","roman":"Satran sanghaaree ih kaanh avtaaree joo ke saadhan ko deh dookh door ko karat hai |","meaning_en":"The destroyer of enemies, Kanh the avatar, removes the bodily sorrows of the saints.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਮਿਤ੍ਰ ਪ੍ਰਿਤਿਪਾਰਕ ਏ ਜਗ ਕੇ ਉਧਾਰਕ ਹੈ ਦੇਖ ਕੈ ਦੁਸਟ ਜਿਹ ਜੀਯ ਤੇ ਜਰਤ ਹੈ। ੪੦੭।","roman":"Mitr pritipaarak e jag ke udhaarak hai dekh kai dusat jih jeey te jarat hai | 407 |","meaning_en":"He sustains his friends and is the saviour of the world; seeing him, the wicked burn in their hearts.","page":398,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":398,"meaning_status":"draft"},{"type":"verse","number":[408],"number_text":"੪੦੮।","page":398,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਸੀਸ ਨਿਵਾਇ ਸਭੈ ਸੁਰ ਆਇਸੁ ਲੈ ਚਲ ਧਾਮਿ ਗਏ ਹੈ।","roman":"Kaanh ko sees nivaai sabhai sur aaisu lai chal dhaami gae hai |","meaning_en":"Bowing their heads to Kanh, all the gods took his leave and went home.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਗੋਬਿੰਦ ਨਾਮ ਧਰਿਯੋ ਹਰਿ ਕੋ ਇਹ ਤੈ ਮਨ ਆਨੰਦ ਯਾਦ ਭਏ ਹੈ।","roman":"Gobind naam dhariyo hari ko ih tai man aanand yaad bhae hai |","meaning_en":"They gave Hari the name Gobind; for this he is remembered with joy in the heart.","page":398,"meaning_status":"draft","note":"ਇਹ ਤੈ ਮਨ ਆਨੰਦ ਯਾਦ ਭਏ: sense uncertain."},{"gurmukhi":"ਰਾਤਿ ਪਰੇ ਚਲਿ ਕੈ ਭਗਵਾਨ ਸੁ ਡੇਰਨਿ ਆਪਨ ਬੀਚ ਅਏ ਹੈ।","roman":"Raati pare chali kai bhagvaan su derni aapan beech ae hai |","meaning_en":"When night fell, the Lord came back to his own dwelling.","page":398,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਤਿ ਭਏ ਜਗ ਕੇ ਦਿਖਬੇ ਕਹੁ ਕੀਨ ਸੁ ਸੁੰਦਰ ਖੇਲ ਨਏ ਹੈ। ੪੦੮।","roman":"Praati bhae jag ke dikhbe kahu keen su sundar khel nae hai | 408 |","meaning_en":"When morning came, he made lovely new plays for the world to see.","page":398,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸ਼ਨਾਵਤਾਰੇ ਇੰਦ੍ਰ ਭੂਲ ਬਖਸਾਵਨ","roman":"Iti sree bachitr naatak granthe krishnaavtaare indr bhool bakhsaavan","meaning_en":"Here ends the chapter named the description of the forgiving of Indra's mistake,","page":398,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਬਰਨਨੰ ਧਿਆਇ ਸਮਾਪਤਮ।","roman":"Naam barannan dhiaai samaaptam |","meaning_en":"in the Krishna Avatar of the holy Bachitar Natak.","page":398,"meaning_status":"draft"}],"page":398}});
